def _naturalness_prompt(report):
    # 기존 verify_naturalness()의 1~9번 카테고리 정의와 완전히 동일(판정 기준 완화 금지 —
    # 사용자 지시). 마지막 지시문만 "자유 텍스트로 나열"에서 "도구로 제출"로 바뀜.
    return (
        "아래는 사주 리포트 본문입니다. 사실 관계가 아니라 '표현이 자연스럽고 명확한가'만 "
        "검토하세요.\n\n"
        "2026-08-29 확장 — 처음엔 아래 1ㆍ2번만 잡았는데, 그 뒤에도 같은 계열의 다른 "
        "실수(연결어미 오용, 지시어 모호성 등)가 실제로 또 나와서 검사 범위를 넓힘. "
        "다음을 찾으세요:\n"
        "1. '겉으로는 ~하지만 속으로는/사실은 ~' 같은 표면-본심 대비 문장인데, 왜 그 둘이 "
        "반대되거나 긴장 관계인지 문장 안에서 설명되지 않은 경우(독자가 '그게 무슨 "
        "뜻이지?'라고 되물어야 하는 경우)\n"
        "2. '튀는 소리', '이중적인 결'같이 무엇을 가리키는지 구체적으로 안 밝혀진 "
        "추상적ㆍ문학적 표현\n"
        "3. '~지만', '~면서도' 같은 대조ㆍ양보 연결어미가, 실제로는 안 부딪히거나 "
        "거의 같은 뜻인 두 내용 사이에 쓰인 경우(예: '단단하지만 잘 안 굽혀지는' — "
        "둘 다 같은 성질의 다른 표현이라 대조가 아니라 겹말인 경우)\n"
        "4. '이', '그', '이 둘' 같은 지시어가 가리키는 대상이 하나로 명확하지 않은 경우 "
        "(특히 여러 특징이 나열된 뒤에 지시어로 뭉뚱그린 경우, 지시어가 그 특징 전체를 "
        "가리키는지 일부만 가리키는지 헷갈리는 경우)\n"
        "5. 사주ㆍ점성술ㆍ타로 용어(십신ㆍ어스펙트 등)를 종류별로 묶어 목록처럼 나열만 "
        "하고 시작하는 문단(예: '조화로운 삼각 다수 — A-B, C-D...'처럼 근거를 먼저 "
        "쭉 늘어놓고 그 다음에야 결론이 나오는 구조)\n"
        "6. 결론(사람 얘기)보다 전문 근거(용어 설명)가 먼저 나오는 문단 — 근거부터 "
        "설명하고 결론은 마지막에 오는 순서로 쓰인 경우\n"
        "7. 계산값이나 용어를 언급만 하고, 그게 이 손님의 실제 삶에서 구체적으로 "
        "어떻게 나타나는지(현실 장면)까지 안 이어간 문장 — 공식만 던지고 이 손님에게 "
        "대입을 안 한 경우\n"
        "8. 장점만 나열하고 그림자(부작용ㆍ대가)나 조언 없이 끝난 문단\n"
        "9. '계산 데이터', '계산값', '분석 체계', '구조적으로 보면', '종합하면', "
        "'기운의 흐름', '알고리즘' 같은 AI 분석 보고서 냄새가 나는 단어\n\n"
        "문제를 찾으면 submit_naturalness_issues 도구로 제출하세요. 각 항목의 "
        "section_kind는 반드시 다음 중 하나여야 합니다: "
        f"{', '.join(sorted(_REWRITABLE_SECTION_KINDS.keys()))}. "
        "quoted_sentence는 아래 리포트 본문에 실제로 있는 문장을 그대로(줄이거나 "
        "바꾸지 않고) 인용하세요 — 나중에 코드가 이 문장이 실제 원문에 있는지 대조해서 "
        "없으면 그 항목을 버립니다. 문제가 없으면 issues를 빈 배열로 제출하세요.\n\n"
        f"[리포트 본문]\n```json\n{json.dumps(report, ensure_ascii=False)}\n```"
    )


# 2026-09-01 추가 — 실제 API 파일럿에서 확인된 사고 대응: 구조화 tool-call이
# max_tokens=1536에서 실제로 잘렸는데(stop_reason=="max_tokens", tool input이 빈 {}),
# 그걸 "issues 없음"으로 잘못 해석해 조용히 PASS를 반환했었다. 4096으로 우선 올리되,
# 이 값을 최종 확정으로 보지 않는다(사용자 지시 — 이번 단계는 게이트 자체를 고치는
# 것이지 이 숫자를 실측으로 확정하는 단계가 아님).
_NATURALNESS_MAX_TOKENS = 4096


def verify_naturalness(report, tier=None, call_fn=None):
    """2026-08-29 추가 — 사용자가 실제 발송된 리포트 문장("겉으로는 튀는 소리를 내면서도
    속으로는 결국 손에 잡히는 결과물을 원하는 이중적인 결")을 보고 지적: 사실은 안 틀렸는데
    표면/본심을 대비시키는 문장이 그 대비의 근거를 안 밝혀서 헷갈리게 읽히고, "튀는 소리"
    같은 추상적 표현이 뭘 가리키는지 안 밝혀져 있었음. verify_groundedness()는 사실 관계만
    보므로 이 문제는 못 잡는다 — 표현 방식 전담 검증이 필요해서 신설.

    같은 원칙: 경고만 남기고 발송을 막지 않으며, 이 함수가 실패해도 파이프라인은 절대 안
    죽는다(이미 돈을 낸 리포트를 이 부가 검증 때문에 날리면 안 됨).

    2026-09-01 수정 — #7~#14 품질개선 폐쇄루프 1단계. 자유 텍스트 대신 구조화된
    tool-call로 문제 목록을 받는다(판정 기준 9개 카테고리는 완전히 동일, 문구도 그대로
    유지 — 응답 "형식"만 바꿈).

    2026-09-01 추가 수정 — Detection Gate. 실제 API 파일럿에서 구조화 응답이
    max_tokens에서 잘려 빈 결과를 "검증 통과"로 잘못 반환한 사고가 실제로 발생함
    (stop_reason=="max_tokens", tool input=={}). 이후로는 다음 4단계 순서로만
    판정한다 — 중간 단계가 하나라도 실패하면 "issues 없음"으로 얼버무리지 않고
    INCOMPLETE/ERROR로 명확히 구분해 반환한다:
      1) stop_reason 확인 — "max_tokens"면 무조건 INCOMPLETE(추측 보정 금지)
      2) tool_use 블록 존재 확인 — 없으면 ERROR
      3) tool input에 "issues" 키가 실제로 있는지(스키마 완전성) — 없으면 INCOMPLETE
      4) issues가 배열이고 각 원소가 dict인지 — 아니면 ERROR
    이 네 단계를 전부 통과했을 때만 issues==[] -> PASS, issues>0 -> ISSUES_FOUND로
    판정한다. 반환값이 list에서 dict({"status","issues","detail"})로 바뀜 — 호출부
    (main())는 반환값을 쓰지 않으므로 이 변경으로 깨지지 않음.

    call_fn을 넘기면 그 함수를 실제 API 대신 쓴다(테스트용 — apply_targeted_rewrite의
    rewrite_fn과 동일한 패턴, resp 객체를 반환해야 함 — stop_reason 속성 포함). 안
    넘기면 실제 API를 호출한다(비용 발생)."""
    if call_fn is None:
        _block_if_offline_test_mode("verify_naturalness")
    try:
        prompt = _naturalness_prompt(report)
        if call_fn is not None:
            resp = call_fn(prompt)
        else:
            client = anthropic.Anthropic()
            # 2026-09-03 — GROUNDEDNESS_MODEL이 claude-sonnet-5로 바뀌면서 함께 필요해진
            # 호환성 조정. call_llm()/_call_targeted_rewrite_llm()과 같은 이유(1575행
            # 주석 참고) — sonnet-5는 thinking을 명시 안 하면 기본으로 적응형 사고가
            # 켜지고, 그러면 이미 빠듯한 max_tokens 예산 일부를 사고에 먼저 써서 구조화
            # 출력이 잘릴 위험이 커진다(이 함수 자체가 막으려는 사고와 같은 종류). 프롬프트ㆍ
            # 스키마ㆍ판정 로직은 전혀 안 바꾸고 이 파라미터만 추가.
            resp = client.messages.create(
                model=GROUNDEDNESS_MODEL, max_tokens=_NATURALNESS_MAX_TOKENS,
                thinking={"type": "disabled"},
                tools=[_NATURALNESS_ISSUES_SCHEMA],
                tool_choice={"type": "tool", "name": "submit_naturalness_issues"},
                messages=[{"role": "user", "content": prompt}],
            )
            api_usage.log_usage_record(api_usage.build_usage_record(
                call_purpose="verify_naturalness", model=GROUNDEDNESS_MODEL, usage=resp.usage,
                tier=tier, thinking_disabled=True,
            ))

        # 1) stop_reason 확인 — 잘린 응답은 절대 PASS/ISSUES_FOUND가 될 수 없음
        stop_reason = getattr(resp, "stop_reason", None)
        if stop_reason == "max_tokens":
            usage = getattr(resp, "usage", None)
            out_tok = getattr(usage, "output_tokens", None)
            print(
                f"⚠ 경고: 자연스러움 검증 응답이 max_tokens에서 잘림(output_tokens={out_tok}) "
                "— 검증이 완료되지 못함, 이 결과를 통과로 간주하지 말 것"
            )
            return {"status": "INCOMPLETE", "issues": [],
                    "detail": f"stop_reason=max_tokens, output_tokens={out_tok}"}

        # 2) tool_use 블록 존재 확인
        tool_block = None
        for block in resp.content:
            if getattr(block, "type", None) == "tool_use" and getattr(block, "name", None) == "submit_naturalness_issues":
                tool_block = block
                break
        if tool_block is None:
            print("⚠ 경고: 자연스러움 검증에서 도구 호출을 찾지 못함 — 검증 실패")
            return {"status": "ERROR", "issues": [], "detail": "tool_use 블록 없음"}

        # 3) tool input 완전성(스키마 확인) — issues 키 자체가 없으면 잘렸거나 깨진 것
        tool_input = tool_block.input
        if not isinstance(tool_input, dict) or "issues" not in tool_input:
            print(
                f"⚠ 경고: 자연스러움 검증 응답이 불완전함(issues 필드 없음: {tool_input!r}) "
                "— 검증이 완료되지 못함, 이 결과를 통과로 간주하지 말 것"
            )
            return {"status": "INCOMPLETE", "issues": [], "detail": f"tool input 불완전: {tool_input!r}"}

        # 4) issues가 배열이고 각 원소가 dict인지
        issues = tool_input["issues"]
        if not isinstance(issues, list) or not all(isinstance(it, dict) for it in issues):
            print("⚠ 경고: 자연스러움 검증 응답의 issues 형식이 올바르지 않음 — 검증 실패")
            return {"status": "ERROR", "issues": [], "detail": f"issues 형식 오류: {issues!r}"}

        # 여기까지 왔으면 응답이 완전하다 — 이제만 issues==[]를 진짜 PASS로 인정
        if not issues:
            print("✓ 표현 자연스러움 검증 통과(응답 완전히 완료됨, 이슈 없음)")
            return {"status": "PASS", "issues": [], "detail": "검증 완료, 이슈 없음"}

        print(
            f"⚠ 경고: 표현이 헷갈리거나 부자연스러운 문장 발견({len(issues)}건) — "
            "발송 전 반드시 사람이 확인할 것:"
        )
        for it in issues:
            loc = str(it.get("section_kind", "?"))
            if it.get("index") is not None:
                loc += f"[{it['index']}]"
            if it.get("system_or_key"):
                loc += f".{it['system_or_key']}"
            if it.get("field"):
                loc += f".{it['field']}"
            print(f"    - ({loc}) {it.get('quoted_sentence', '')!r} — {it.get('category')}번 항목: {it.get('reason', '')}")
        return {"status": "ISSUES_FOUND", "issues": issues, "detail": f"{len(issues)}건 발견"}
    except Exception as e:  # noqa: BLE001 — 이 검증이 죽어도 본 파이프라인은 계속돼야 함
        print(f"⚠ 참고: 자연스러움 검증 호출 실패({e}) — 이 검증만 건너뜀, 리포트 생성 자체엔 영향 없음")
        return {"status": "ERROR", "issues": [], "detail": str(e)}


# ---- path 검증 — LLM이 만든 자유 path를 그대로 신뢰하지 않는다 ----

_WS_RE_REWRITE_MATCH = re.compile(r"\s+")


def _norm_ws_rewrite_match(s):
    """quoted_sentence 위치 대조 전용 normalization. 공백 정규화에 더해, 인라인
    마크다운 강조 기호(**)만 제거한다 — 2026-09-01, 실제 API 파일럿에서 확인된
    사고 대응: 원문은 "...구조**로 볼 수 있습니다"처럼 문장 중간에 ** 가 걸쳐 있는데,
    LLM이 quoted_sentence를 인용할 때 이 기호만 자연스럽게 빼고 인용하는 경우가
    실제로 있었다(내용은 완전히 같은데 ** 유무만 다름) — 공백만 정규화하던 기존
    로직은 이걸 "위치 특정 실패"로 오판해 유효한 issue를 부당하게 폐기했다.

    이 함수는 오직 report 문자열과 quoted_sentence를 "비교할 때만" 쓰는 임시
    정규화이고, report 원문 자체나 apply_targeted_rewrite에 넘어가는 실제 값은
    전혀 건드리지 않는다 — ** 제거 외의 다른 차이(단어 추가/삭제/치환, 동의어,
    유사도 등)는 지금까지와 똑같이 전부 불일치로 취급한다(의도적으로 좁은 허용
    범위, 사용자 지시)."""
    s = str(s or "").replace("**", "")
    return _WS_RE_REWRITE_MATCH.sub(" ", s).strip()


def resolve_naturalness_issue_path(report, issue):
    """issue(section_kind/index/system_or_key/field/quoted_sentence)를 실제 report의
    path 튜플로 조립하고 검증한다. section_kind+index+system_or_key+field 4개 값만
    받아 코드가 닫힌 whitelist(_REWRITABLE_SECTION_KINDS)로 path를 조립한다 — LLM이
    ["system_sections", 999, "body"] 같은 자유 path 문자열을 직접 만들게 하지 않는다
    (사용자 지시).

    하나라도 실패하면 (None, 실패사유)를 반환한다 — 비슷한 path를 찾아 추측 보정하지
    않는다(사용자 지시 그대로)."""
    if not isinstance(issue, dict):
        return None, "issue가 dict가 아님"

    kind = issue.get("section_kind")
    spec = _REWRITABLE_SECTION_KINDS.get(kind)
    if spec is None:
        return None, f"허용되지 않은 section_kind: {kind!r}"

    path = [kind]
    if spec["needs_index"]:
        idx = issue.get("index")
        if not isinstance(idx, int) or isinstance(idx, bool):
            return None, f"index가 정수가 아님: {idx!r}"
        path.append(idx)
    if spec["needs_key"]:
        key = issue.get("system_or_key")
        if not isinstance(key, str) or not key:
            return None, f"system_or_key가 없음: {key!r}"
        path.append(key)
    if spec["allowed_fields"] is not None:
        field = issue.get("field")
        if field not in spec["allowed_fields"]:
            return None, f"허용되지 않은 field: {field!r}(section_kind={kind!r})"
        path.append(field)
    path = tuple(path)

    try:
        value = _get_by_path(report, path)
    except (KeyError, IndexError, TypeError) as e:
        return None, f"path 접근 실패({type(e).__name__}): {path}"

    if not isinstance(value, str):
        return None, f"대상 값이 문자열이 아님(실제: {type(value).__name__}), path={path}"

    quoted = issue.get("quoted_sentence")
    if not isinstance(quoted, str) or not quoted.strip():
        return None, "quoted_sentence가 없음"
    if _norm_ws_rewrite_match(quoted) not in _norm_ws_rewrite_match(value):
        return None, "quoted_sentence가 실제 필드 원문에 없음(위치 특정 실패)"

    return path, None


def locate_target_paragraph(field_text, quoted_sentence):
    """field_text를 "\n\n" 기준 문단으로 나누고, quoted_sentence가 정확히 몇 개의
    문단에 들어있는지 확인한다 — resolve_naturalness_issue_path()가 확보한 "field 존재"
    검증 다음 단계로, quoted_sentence가 실제로 가리키는 최소 수정 단위(문단)를 찾는다.

    2026-09-01 추가 — paragraph-level 폐쇄 루프 근본 원인 제거(§4). 문단 분리ㆍ판정은
    전부 기존 로직 재사용(_is_content_paragraph, _norm_ws_rewrite_match) — 새 정규화ㆍ
    새 유사도 판정을 만들지 않는다.

    반환: (index, paragraphs, matched_count, err).
      - 정확히 1개 문단에 매칭 -> (그 index, 전체 paragraphs 리스트, 1, None)
      - 0개 매칭 -> (None, paragraphs, 0, "NOT_FOUND: ...")
      - 2개 이상 매칭 -> (None, paragraphs, N, "AMBIGUOUS: ...") — 추측 금지, 임의로
        첫 번째를 고르지 않는다(사용자 지시 원칙 3/5).
    matched_count는 실패 시에도 항상 반환한다 — 진단ㆍ테스트에서 "몇 개에 매칭됐는지"를
    accepted 여부와 무관하게 확인할 수 있어야 하므로(사용자 지시 §15)."""
    paragraphs = field_text.split("\n\n")
    quoted_norm = _norm_ws_rewrite_match(quoted_sentence)
    matches = [
        i for i, p in enumerate(paragraphs)
        if _is_content_paragraph(p) and quoted_norm in _norm_ws_rewrite_match(p)
    ]
    if len(matches) == 1:
        return matches[0], paragraphs, 1, None
    if len(matches) == 0:
        return None, paragraphs, 0, "NOT_FOUND: quoted_sentence가 어느 문단에도 없음"
    return None, paragraphs, len(matches), f"AMBIGUOUS: {len(matches)}개 문단에 매칭됨(임의 선택 금지)"


# ---- STEP 3: targeted rewrite 폐쇄 루프 — 결과를 자동으로 신뢰하지 않는다 ----

DEFAULT_MAX_REWRITES_PER_FIELD = 1  # 필드당 재시도 없음 — 실패하면 그걸로 끝, 무한 루프 방지

# 2026-09-01 — 리포트당 상한. 근거: 10회 naturalness 재분석에서 카테고리 1/5/6/7(재작성
# 대상)만 센 리포트당 평균은 4.2건(42/10), 관찰된 최댓값은 9건(single/master 실행분).
# 상한을 최댓값(9)으로 두면 비용 통제 의미가 옅어지고, 평균(4.2) 그대로 두면 편차가 큰
# 리포트에서 개선이 덜 미친다 — 평균에 여유분을 더한 6을 제안값으로 둔다. 확정된 값이
# 아니라 실제 pilot 이후 재조정을 전제로 한 초기값(사용자 지시대로 임의 확정 안 함).
DEFAULT_MAX_REWRITES_PER_REPORT = 6


def _rewrite_within_reasonable_scope(original, rewritten):
    """재작성 결과가 원문과 지나치게 다른 분량이면(지시 범위를 벗어난 과도한 재작성일
    가능성) False를 반환한다.

    2026-09-01 — 중요한 한계를 그대로 밝힘: _call_targeted_rewrite_llm이 아직 한 번도
    실제로 실행된 적이 없어(미승인), 실제 재작성 결과 데이터로 임계값을 도출할 수
    없었다. 아래 0.5~2.0배는 "원문의 절반 미만이거나 두 배를 넘으면 의심스럽다"는
    보수적인 초기값일 뿐 실측 근거는 아니다 — 실제 API pilot 이후 재조정이 반드시
    필요하다(사용자 지시: 기준을 확정하기 어려우면 구현 전에 보고할 것 — 코드에는
    넣되 이 한계를 명시적으로 남긴다)."""
    if not original or not rewritten:
        return False
    ratio = len(rewritten) / len(original)
    return 0.5 <= ratio <= 2.0


def _field_groundedness_prompt(computed, field_text):
    """2026-09-01 수정 — ROOT CAUSE B 대응(STEP 2 실제 pilot: 계산값에 shi_shen_zhi=
    ["편재","칠살(편관)"]가 실제로 있었는데도, groundedness가 scalar shi_shen_gan="정관"만
    보고 "편재는 년주에 없다"고 오판해 정상 rewrite가 rollback됨 — computed 데이터 자체는
    누락 없이 전달되고 있었음을 로그/fixture로 직접 확인했고, 원인은 이 프롬프트가
    shi_shen_gan/shi_shen_zhi 두 필드의 의미ㆍ관계를 전혀 설명하지 않아 모델이 어느
    필드를 봐야 하는지 판단할 근거가 없었던 것으로 특정됨(사전 조사, 코드 미변경 상태로
    로그ㆍfixture 대조 완료).

    computed 전체를 그대로 넘기는 기존 계약, "OK"/한 문장 출력 계약은 그대로 유지 —
    추가하는 건 sipsin 필드 두 개의 관계를 읽는 법과, "list 중 하나만 언급"과 "유일값
    단정/list 전체 왜곡"을 구분하라는 지시뿐이다. 과거 pilot(월주/비견 사례 — shi_shen_zhi
    list 중 하나만 narrate한 걸 "list 전체를 대표"한다고 오판한 사례)도 이 구분으로
    같이 다룬다. 기준을 느슨하게 만드는 게 목적이 아니므로, computed에 없는 값ㆍ다른
    기둥의 값ㆍlist에 없는 값ㆍ유일값으로 왜곡한 경우는 여전히 FAIL 대상임을 명시한다."""
    return (
        "아래 문장 하나가 계산값과 어긋나는 구체적 사실을 담고 있는지만 확인하세요. "
        "문체ㆍ표현은 평가 대상이 아닙니다.\n\n"
        "[십신 필드 읽는 법 — 사주 기둥(년주/월주/일주/시주) 관련 주장에만 해당]\n"
        "각 기둥의 shi_shen_gan은 그 기둥 천간의 십신 하나이고, shi_shen_zhi는 그 기둥 "
        "지지ㆍ지장간에서 나오는 십신 목록으로 여러 개일 수 있습니다. \"OO주의 XX(십신)\" "
        "같은 표현을 검증할 때는 shi_shen_gan만이 아니라 shi_shen_zhi도 함께 확인하세요. "
        "shi_shen_zhi 목록 중 하나만 언급하는 것은 그 자체로 근거 없음이 아닙니다 — 다만 "
        "문장이 그 하나를 \"그 기둥의 유일한 십신\"이라고 단정하거나, 목록의 나머지가 "
        "없다고 말하거나, 목록 전체를 그 하나와 동일시하면 그 부분은 여전히 근거 없는 "
        "주장입니다. 계산값에 없는 값, 다른 기둥의 값을 가져다 쓴 경우도 마찬가지로 "
        "근거 없는 주장입니다.\n\n"
        f"[계산값]\n```json\n{json.dumps(computed, ensure_ascii=False)}\n```\n\n"
        f"[검토할 문장]\n{field_text}\n\n"
        "계산값과 어긋나거나 근거 없는 구체적 주장이 없으면 \"OK\"라고만 답하세요. "
        "있으면 무엇이 문제인지 한 문장으로 답하세요."
    )


def verify_field_groundedness(computed, field_text, call_fn=None):
    """apply_targeted_rewrite() 결과 하나만 대상으로 하는 축소판 groundedness 검사.
    verify_groundedness()처럼 report 전체를 다시 보내지 않고, 이 필드+computed.json만
    보낸다(토큰ㆍ비용 절약 — 사용자 지시).

    call_fn을 넘기면 그 함수를 실제 API 대신 쓴다(테스트용, prompt를 받아 결과 텍스트를
    반환해야 함). 안 넘기면 실제 API를 호출한다(비용 발생)."""
    if call_fn is None:
        _block_if_offline_test_mode("verify_field_groundedness")
    try:
        prompt = _field_groundedness_prompt(computed, field_text)
        if call_fn is not None:
            result_text = call_fn(prompt)
        else:
            client = anthropic.Anthropic()
            # 2026-09-03 — sonnet-5 호환성 조정(위 verify_naturalness와 동일 이유). 이
            # 호출은 max_tokens=256으로 특히 여유가 없어, thinking이 조용히 켜지면 짧은
            # "OK"/사유 문장 자체가 잘릴 위험이 더 크다.
            resp = client.messages.create(
                model=GROUNDEDNESS_MODEL, max_tokens=256,
                thinking={"type": "disabled"},
                messages=[{"role": "user", "content": prompt}],
            )
            api_usage.log_usage_record(api_usage.build_usage_record(
                call_purpose="field_groundedness", model=GROUNDEDNESS_MODEL, usage=resp.usage,
                tier=None, thinking_disabled=True,
            ))
            result_text = "".join(
                b.text for b in resp.content if getattr(b, "type", None) == "text"
            ).strip()
        return result_text.upper().startswith("OK"), result_text
    except Exception as e:  # noqa: BLE001 — 이 검증도 죽으면 안 됨(호출부가 안전 쪽으로 처리)
        return False, f"검증 호출 실패: {e}"


# 2026-09-01 추가 — 실제 targeted rewrite 파일럿(2회차)에서 재현된 사고 대응: groundedness/
# scope를 전부 통과한 rewrite 결과 문자열 끝에 "</new_value>\n</invoke>\n"라는 도구
# 호출 프로토콜 잔재가 그대로 섞여 있었다. 4개 태그만 하드코딩하지 않고, "이 파이프라인
# 자신의 tool-call 스키마가 실제로 쓰는 예약어"(_FIELD_REWRITE_SCHEMA의 도구/파라미터
# 이름)에 일반적인 agentic tool-use 프로토콜의 구조 태그명을 더한 것을 기준 집합으로
# 삼는다 — category9(내부 필드명 노출)와 같은 설계 원칙("소스에서 파생, 하드코딩 최소화").
_TOOL_PROTOCOL_TAG_NAMES = frozenset({
    "invoke", "parameter", "parameters", "function_calls", "function_results",
    "tool_call", "tool_use", "tool_result", "tool_calls",
    "antml:invoke", "antml:parameter", "antml:function_calls", "antml:function_results",
}) | {_FIELD_REWRITE_SCHEMA["name"]} | set(_FIELD_REWRITE_SCHEMA["input_schema"]["properties"].keys())

# 열림/닫힘 태그 형태("<이름 ...>" 또는 "</이름>")만 잡는다 — 문장 속에 우연히 등장하는
# "<"/">" 낱개 기호나 마크다운(**)은 애초에 이 정규식의 태그 모양 자체와 안 맞아 매치되지
# 않는다(사용자 지시: 정상 콘텐츠를 과도하게 차단하지 않을 것).
_XML_TAG_RE = re.compile(r"</?([a-zA-Z][a-zA-Z0-9_:.\-]*)\b[^>]*>")


def check_format_integrity(text):
    """rewrite 결과 문자열에 tool-call/XML 프로토콜 잔재가 섞여 있는지 결정론적으로
    검사한다(LLM에게 판단시키지 않음, 사용자 지시). 태그 이름이 _TOOL_PROTOCOL_TAG_NAMES와
    일치할 때만 오염으로 판정 — 일반 텍스트의 "<"/">" 기호나 마크다운 강조는 태그 모양
    자체가 아니라서 애초에 매치되지 않는다.

    반환: {"passed": bool, "reason": str, "matched_pattern": str|None}"""
    if not isinstance(text, str) or not text:
        return {"passed": True, "reason": "", "matched_pattern": None}
    for m in _XML_TAG_RE.finditer(text):
        tag_name = m.group(1).lower()
        if tag_name in _TOOL_PROTOCOL_TAG_NAMES:
            return {
                "passed": False,
                "reason": "tool-call protocol residue detected",
                "matched_pattern": m.group(0),
            }
    return {"passed": True, "reason": "", "matched_pattern": None}


def rewrite_and_validate_issue(report, computed, issue, rewrite_fn=None, groundedness_call_fn=None):
    """감지된 naturalness issue 하나를 대상으로 path 검증 → paragraph 위치 확정 → 재작성
    → 검증(타입ㆍparagraph 경계ㆍ변경범위ㆍparagraph-level groundednessㆍformat integrity)
    → 채택/롤백까지 전부 수행한다. 검증을 전부 통과했을 때만 report에 반영한다(실패하면
    report는 애초에 손도 대지 않은 상태로 남는다 — apply_targeted_rewrite 참고).

    2026-09-01 수정 — paragraph-level 폐쇄 루프 근본 원인 제거. 예전엔 field 전체를
    수정ㆍ검증 단위로 삼아서, 같은 field 안 무관한 다른 문단의 기존 문제가 정상 rewrite
    까지 rollback시키는 사고가 실제 pilot(single tier Issue A)에서 발생했다. 이제
    quoted_sentence가 실제로 속한 문단 하나만 확정해(locate_target_paragraph) 그 문단만
    재작성ㆍ검증ㆍ반영한다 — 나머지 문단은 splice 구조상 코드가 건드릴 방법 자체가 없다
    (LLM의 "손대지 말라"는 지시 준수 여부에 의존하지 않음).

    반환: {"accepted": bool, "path": tuple|None, "stage": str, "reason": str,
           "new_value": str|None(=새 paragraph), "paragraph_index": int|None,
           "matched_paragraph_count": int, ...}. 실패해도 실제 API가 생성한 new_value
    (paragraph 텍스트)를 반환값에 남긴다(진단ㆍ로그ㆍ테스트용) — report 자체에는 반영하지
    않는다. 모든 실패 경로에서 new_value/paragraph_index/matched_paragraph_count 키가
    항상 존재하도록 채워, 호출부가 매번 `.get` 없이 일관되게 다룰 수 있게 한다."""
    path, err = resolve_naturalness_issue_path(report, issue)
    if path is None:
        return {"accepted": False, "path": None, "stage": "path_resolution", "reason": err,
                "new_value": None, "paragraph_index": None, "matched_paragraph_count": 0}

    field_text = _get_by_path(report, path)
    paragraph_index, paragraphs, matched_count, loc_err = locate_target_paragraph(
        field_text, issue.get("quoted_sentence", ""),
    )
    if paragraph_index is None:
        return {"accepted": False, "path": path, "stage": "paragraph_location", "reason": loc_err,
                "new_value": None, "paragraph_index": None, "matched_paragraph_count": matched_count}

    original_paragraph = paragraphs[paragraph_index]

    result = apply_targeted_rewrite(
        report, computed, path, paragraph_index, issue.get("reason", ""), rewrite_fn=rewrite_fn,
    )
    new_paragraph = result["new_paragraph"]

    def _fail(stage, reason, **extra):
        return {"accepted": False, "path": path, "stage": stage, "reason": reason,
                "new_value": new_paragraph, "paragraph_index": paragraph_index,
                "matched_paragraph_count": matched_count, **extra}

    # 검사 A — 문자열 여부
    if not isinstance(new_paragraph, str) or not new_paragraph.strip():
        return _fail("type_check",
                      f"rewrite 결과가 문자열이 아니거나 비어있음(실제: {type(new_paragraph).__name__})")

    # 검사 신규 — paragraph 경계 침범(§10). LLM이 반환한 문단 안에 새 빈 줄("\n\n")이
    # 생기면 paragraph-level 계약(반환값은 정확히 문단 하나) 위반 — 추측으로 다시
    # 분할해 여러 문단에 적용하지 않고 fail-closed 처리한다.
    if "\n\n" in new_paragraph:
        return _fail("paragraph_structure", "rewrite 결과에 빈 줄(문단 구분)이 새로 생겨 paragraph 경계를 침범함")

    # 검사 E — 변경 범위(길이 비율). 이제 field 전체가 아니라 문단 대 문단으로 비교한다
    # (§8 — 함수/임계값 자체는 무수정, 비교 대상만 축소).
    if not _rewrite_within_reasonable_scope(original_paragraph, new_paragraph):
        return _fail("scope_check",
                      f"길이 비율이 허용 범위 밖(원본 문단 {len(original_paragraph)}자 -> 신규 {len(new_paragraph)}자)")

    # 검사 C — paragraph-level groundedness(§7). 다른 문단은 애초에 이 프롬프트에
    # 실리지 않으므로, 다른 문단의 기존 오류가 이 결과에 영향을 줄 수 없다.
    ok, detail = verify_field_groundedness(computed, new_paragraph, call_fn=groundedness_call_fn)
    if not ok:
        return _fail("groundedness", detail)

    # 검사 D — Format Integrity(§9), 이제 문단 대상. 함수 자체는 무수정.
    integrity = check_format_integrity(new_paragraph)
    if not integrity["passed"]:
        return _fail("format_integrity", integrity["reason"], matched_pattern=integrity["matched_pattern"])

    # 전부 통과 — 이제야 report에 실제로 반영한다(splice-back, §6). 다른 문단은 이
    # join 대상 리스트 안에서 인덱스만 유지된 채 원본 그대로 남는다 — 코드 구조상
    # target 문단 외에는 물리적으로 바뀔 방법이 없다.
    paragraphs[paragraph_index] = new_paragraph
    _set_by_path(report, path, "\n\n".join(paragraphs))

    return {"accepted": True, "path": path, "old_value": original_paragraph, "new_value": new_paragraph,
            "paragraph_index": paragraph_index, "matched_paragraph_count": matched_count}


_ISSUE_ECHO_FIELDS = ("category", "quoted_sentence", "section_kind", "index", "system_or_key", "field")

# 이 폐쇄 루프가 처리하지 못한 issue의 결과에도 항상 채워 넣는 공통 필드 —
# rewrite_and_validate_issue()의 성공/실패 반환 shape과 동일한 키 집합을 유지해
# 호출부가 "이 issue는 어떤 stage를 거쳤나"만 보고 성공/실패 결과 전체를 일관되게
# 다룰 수 있게 한다(사용자 지시 — issue가 결과에서 사라지면 안 됨).
_UNATTEMPTED_RESULT_BASE = {
    "path": None, "new_value": None, "paragraph_index": None, "matched_paragraph_count": 0,
}


def _echo_issue_fields(issue):
    return {k: issue.get(k) for k in _ISSUE_ECHO_FIELDS}


# 2026-09-03 — 이전엔 target_categories 기본값이 (1,5,6,7)(근거ㆍ연결 부족 계열,
# 실제 경고의 58.3%)로 좁혀져 있었다. 이건 "카테고리 2/3/4/8은 이 구조로 못 고친다"는
# 기술적 제약이 아니라, 가장 큰 공통원인 묶음부터 먼저 닫힌 루프를 검증하기 위한
# 범위 결정이었다(사용자 지시로 재확인) — rewrite/scope/groundedness/format_integrity
# 전부 category 번호를 전혀 참조하지 않는 범용 로직이고, issue.reason이 그대로
# rewrite 프롬프트의 "문제로 지적된 내용"에 실리므로 카테고리 2(추상적 표현)ㆍ
# 3(대조어미 오용/겹말)ㆍ4(지시어 모호)ㆍ8(장점만 나열)도 구조적으로 동일하게
# 처리 가능함을 코드 추적+mock 전체 경로 테스트(Test CAT2~CAT8)로 확인했다.
# 카테고리 9(내부 필드명 노출)만 계속 제외한다 — scan_report_for_internal_field_leaks()
# 라는 별도의, 더 정밀한(정확한 key 이름 대조) 결정론적 경로가 이미 있고, 이 범용
# LLM rewrite 경로로 중복 처리하면 두 메커니즘이 서로 다른 판정을 내릴 여지만 생긴다
# (기존 세션에서 이미 결정된 "카테고리9는 별도 경로" 설계를 그대로 유지).
_ALL_REWRITABLE_NATURALNESS_CATEGORIES = (1, 2, 3, 4, 5, 6, 7, 8)


def run_targeted_rewrite_pass(report, computed, issues, rewrite_fn=None, groundedness_call_fn=None,
                               target_categories=_ALL_REWRITABLE_NATURALNESS_CATEGORIES,
                               max_rewrites_per_report=DEFAULT_MAX_REWRITES_PER_REPORT):
    """구조화된 naturalness issues 중 target_categories(기본 1~8 전부 — 카테고리 9만
    제외)만 골라 상한 안에서 하나씩 rewrite_and_validate_issue()에 넘긴다. 필드당
    재시도 없음(DEFAULT_MAX_REWRITES_PER_FIELD=1) — 실패하면 그 필드는 원문 그대로
    두고 다음으로 넘어간다. 카테고리 9는 대상에서 제외(별도 결정론적 경로,
    scan_report_for_internal_field_leaks 참고, _ALL_REWRITABLE_NATURALNESS_CATEGORIES
    설명 참고) — 이 폐쇄 루프가 다루지 않는 카테고리는 "out_of_scope_category"로
    명시 기록한다(2026-09-03 이전엔 1/5/6/7만 대상이라 2/3/4/8도 여기 해당했으나,
    구조 조사+mock 전체 경로 검증 후 전부 대상에 포함시킴 — 이제 실제로 이 stage에
    도달하는 건 category 9뿐).

    2026-09-02 수정 — 품질 원칙 강화: 이전엔 category 불일치(continue)나
    max_rewrites_per_report 초과(break) 시 그 issue가 반환값에서 그냥 사라졌다
    (추적 불가능한 silent 누락 — "일부만 처리하고 나머지는 결과에서 사라지는 경로"가
    실제로 존재했음). 또한 rewrite_and_validate_issue() 안에서 예외가 발생하면
    이 함수 전체가 죽어서, 이미 처리된 결과까지 포함해 아무것도 반환되지 않고
    이후 issue 전부가 함께 사라졌다(verify_naturalness/verify_field_groundedness는
    자기 자신을 try/except로 감싸 파이프라인을 안 죽이는 원칙을 이미 따르고 있었는데
    이 함수만 그 원칙이 빠져 있었음).

    이제 반환값은 issues와 **정확히 같은 길이**이며, 원소 하나하나가 항상 다음 중
    하나의 stage를 갖는다 — 어떤 경우에도 issue가 사라지지 않는다:
      - accepted=True (성공)
      - rewrite_and_validate_issue()의 기존 실패 stage들(type_check/paragraph_structure/
        scope_check/groundedness/format_integrity/paragraph_location/path_resolution)
      - "out_of_scope_category" — target_categories 밖(사람이 검토해야 함, 자동 해결
        대상이 아님을 명시. category 9도 여기 포함 — 별도 결정론적 경로가 있다고 해서
        이 함수의 issues 인자에 섞여 들어온 것까지 조용히 지우지 않는다)
      - "skipped_cap" — max_rewrites_per_report 초과로 미시도
      - "exception" — 처리 중 예외 발생(이 issue 하나만 실패로 기록, 나머지 issue
        처리는 계속됨)
    각 결과에는 원본 issue의 category/quoted_sentence/section_kind/index/
    system_or_key/field를 그대로 echo한다 — path가 같은 issue가 둘 이상이어도
    어느 결과가 어느 원본 issue에 대응하는지 항상 구분 가능하게 한다(이전엔 이
    정보가 전혀 없었음). is_naturalness_pass_complete()가 이 반환값을 그대로 소비한다."""
    results = []
    attempted = 0
    _accepted_field_targets = set()
    for issue in issues:
        base = _echo_issue_fields(issue)
        if issue.get("category") not in target_categories:
            results.append({
                **base, **_UNATTEMPTED_RESULT_BASE, "accepted": False, "stage": "out_of_scope_category",
                "reason": f"category {issue.get('category')!r}는 이 폐쇄 루프의 자동 대상이 아님(수동 검토 필요)",
            })
            continue
        if attempted >= max_rewrites_per_report:
            results.append({
                **base, **_UNATTEMPTED_RESULT_BASE, "accepted": False, "stage": "skipped_cap",
                "reason": f"리포트당 상한({max_rewrites_per_report}) 초과로 미시도",
            })
            continue
        attempted += 1
        try:
            result = rewrite_and_validate_issue(
                report, computed, issue, rewrite_fn=rewrite_fn, groundedness_call_fn=groundedness_call_fn,
            )
        except Exception as e:  # noqa: BLE001 — 이 issue 하나의 예외가 나머지 issue 처리를 막으면 안 됨
            result = {**_UNATTEMPTED_RESULT_BASE, "accepted": False, "stage": "exception", "reason": str(e)}
        # 2026-09-02 추가 — 같은 field를 가리키는 이전 issue가 이미 이번 pass 안에서
        # ACCEPT됐는데 이번 issue가 path_resolution/paragraph_location에서 실패했다면,
        # "quoted_sentence가 원래부터 없었다"와 "직전 rewrite가 그 자리를 바꿔서 지금은
        # 없다"를 구분해 표시한다 — 둘 다 실패 처리(fail-closed)는 동일하지만, 진단
        # 사유가 완전히 다르므로(Detection이 틀린 게 아니라 같은 배치 안 처리 순서
        # 때문) 이 구분이 없으면 "Detection이 잘못됐다"로 오인할 위험이 있다.
        target_key = (issue.get("section_kind"), issue.get("index"), issue.get("system_or_key"), issue.get("field"))
        if result.get("accepted") is not True and result.get("stage") in ("path_resolution", "paragraph_location") \
                and target_key in _accepted_field_targets:
            result = {**result, "stale_due_to_earlier_rewrite_in_this_pass": True}
        elif result.get("accepted") is True:
            _accepted_field_targets.add(target_key)
        results.append({**base, **result})
    return results


def is_naturalness_pass_complete(detection_result, rewrite_results):
    """Detection→rewrite 사이클 전체가 "완료"로 판정될 수 있는지 확인한다.

    2026-09-02 신설 — 품질 원칙: "대체로 잘 됐다"를 성공 기준으로 쓰지 않는다.

    False를 반환하는 경우(전부 명시적):
      - detection_result["status"]가 PASS/ISSUES_FOUND가 아님(INCOMPLETE/ERROR —
        잘린 응답을 완료로 취급하는 사고를 이 레벨에서도 다시 막는다)
      - rewrite_results 길이가 detection_result["issues"] 길이와 다름(누락 탐지 —
        run_targeted_rewrite_pass()가 정상이라면 항상 같은 길이를 반환하므로,
        다르면 그 자체가 상위 호출부의 버그 신호)
      - rewrite_results 중 하나라도 accepted가 True가 아님 — "out_of_scope_category"
        (사람이 아직 검토 안 함)ㆍ"skipped_cap"ㆍ실패ㆍ예외를 전부 미해결로 취급한다.
        category가 이 폐쇄 루프의 자동 대상이 아니라는 사실은 "해결됨"의 이유가
        되지 않는다.

    True를 반환하는 경우: issues가 전부 빈 배열이거나(Detection PASS), 전부
    accepted=True로 실제 처리됨."""
    if detection_result.get("status") not in ("PASS", "ISSUES_FOUND"):
        return False
    issues = detection_result.get("issues") or []
    if len(rewrite_results) != len(issues):
        return False
    return all(r.get("accepted") is True for r in rewrite_results)


def collect_known_terms(computed):
    """computed.json 안에 실제로 존재하는 용어(간지ㆍ별자리ㆍ카드명 등)를 전부 모은다."""
    terms = set()

    def walk(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                walk(v)
        elif isinstance(obj, list):
            for v in obj:
                walk(v)
        elif isinstance(obj, str) and 1 < len(obj) <= 20:
            terms.add(obj)

    walk(computed)
    return terms


def collect_valid_years(computed):
    """se_un/dae_yun/생년 등 computed.json에 실제로 등장하는 '정당한' 연도만 모은다.
    이 목록 밖의 연도가 리포트에 나오면 se_un 없이 AI가 일반 지식으로 채운 것일 가능성이
    높다(실사용 테스트에서 실제로 발견된 문제 — build_report.py 8번 규칙 참고)."""
    years = set()
    saju = computed.get("saju") or {}
    if saju.get("birth_solar"):
        years.add(int(saju["birth_solar"][:4]))
    for entry in saju.get("se_un") or []:
        years.add(entry["year"])
    for entry in saju.get("dae_yun") or []:
        years.add(entry["start_year"])
        years.add(entry["end_year"])
    return years


_PDF_FONT_CMAP = None


def _pdf_font_cmap():
    """PDF에 실제로 쓰이는 Pretendard-Regular.ttf의 글리프 테이블(cmap)을 읽어, 이 폰트가
    그릴 수 있는 유니코드 코드포인트 집합을 반환한다(최초 호출 때만 파일을 읽고 캐시함).
    Pretendard 6종 굵기는 전부 같은 글자 집합을 공유하므로 Regular 하나만 확인하면 된다."""
    global _PDF_FONT_CMAP
    if _PDF_FONT_CMAP is None:
        font_path = HERE / "fonts" / "Pretendard-Regular.ttf"
        _PDF_FONT_CMAP = set(TTFont(str(font_path)).getBestCmap().keys())
    return _PDF_FONT_CMAP


def _is_glyph_supported(ch):
    # 공백ㆍ줄바꿈 등 제어문자는 애초에 그려지는 글자가 아니므로 항상 통과.
    if ch.isspace() or ord(ch) < 0x20:
        return True
    return ord(ch) in _pdf_font_cmap()


_PAREN_LEADING_SEP_RE = re.compile(r"\(\s*[,ㆍ·]+\s*")
_PAREN_TRAILING_SEP_RE = re.compile(r"[\s,ㆍ·]+\)")
_PAREN_EMPTY_RE = re.compile(r"\(\s*[,ㆍ·]*\s*\)")


def _strip_unsupported_glyphs(text):
    """2026-08-24 추가 — 사용자 지시: "경고만 하지 말고, 폰트가 완벽하게 그릴 수 있는
    글자만 쓰도록 만들어라. 한자는 빼버려라." check_hallucination()의 경고는 사람이 보고
    다시 생성 버튼을 눌러야만 고쳐지는데, 그러면 같은 문제가 계속 재발할 여지가 남는다.
    대신 여기서 폰트가 못 그리는 글자를 실제로 제거해서, 그 문제 자체가 최종 산출물에
    나갈 수 없게 만든다. 한자만 쏙 빠지면 "화개살(壬辰)" → "화개살()"처럼 빈 괄호나
    "임진(壬辰, 물의 기운)" → "임진(, 물의 기운)"처럼 군더더기 구두점이 남을 수 있어
    그것도 같이 정리한다."""
    if not text:
        return text
    cleaned = "".join(ch for ch in text if _is_glyph_supported(ch))
    cleaned = _PAREN_LEADING_SEP_RE.sub("(", cleaned)
    cleaned = _PAREN_TRAILING_SEP_RE.sub(")", cleaned)
    cleaned = _PAREN_EMPTY_RE.sub("", cleaned)
    cleaned = re.sub(r" {2,}", " ", cleaned)
    return cleaned


# 2026-08-29 추가 — 실제 사고 발견(사용자 검수): "여왕에서 시종으로 흘러간다는 게
# 흥미운 지점입니다"처럼 LLM이 맞춤법을 틀린 사례가 실제로 있었다. "이 오타 하나는
# 너무 좁아서 규칙까지 만들 필요 없다"는 판단으로 그 파일 하나만 손으로 고치려
# 했었는데, 사용자가 명시적으로 반려함: "고칠때에는 영구적으로 고치도록 해." 그래서
# 한 번 확인된 오타는 전부 여기 사전에 등록해 모든 리포트에서 자동 교정한다 — 다음에
# 새 오타가 발견되면 이 사전에 한 줄만 추가하면 영구히 막힌다(같은 실수를 손으로
# 다시 고치는 게 아니라).
_KNOWN_TYPO_FIXES = {
    "흥미운": "흥미로운",
}


def _fix_known_typos(text):
    for wrong, right in _KNOWN_TYPO_FIXES.items():
        if wrong in text:
            text = text.replace(wrong, right)
    return text


def sanitize_report(obj):
    """report(dict) 전체를 재귀적으로 훑어 모든 문자열 값에서 PDF 폰트가 못 그리는 글자를
    제거한다. intro/body/heading처럼 필드를 하나하나 골라 처리하면 스키마에 필드가 추가될
    때마다 또 빠뜨릴 위험이 있으므로(실제로 이번에 그렇게 놓쳤었음), 구조를 가리지 않고
    모든 문자열을 훑는 일반적인 방식을 쓴다.

    2026-08-29 추가 — 같은 이유로 알려진 맞춤법 오타(_KNOWN_TYPO_FIXES)도 여기서 함께
    교정한다 — 폰트 안전화와 같은 성격(생성 이후 최종 산출물에 결함이 남을 수 없게
    구조적으로 막는 것)이라 같은 재귀 훑기에 얹는 게 자연스럽다."""
    if isinstance(obj, str):
        return _fix_known_typos(_strip_unsupported_glyphs(obj))
    if isinstance(obj, list):
        return [sanitize_report(v) for v in obj]
    if isinstance(obj, dict):
        return {k: sanitize_report(v) for k, v in obj.items()}
    return obj


_SCHEMA_TYPE_CHECK = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "null": lambda v: v is None,
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "integer": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "boolean": lambda v: isinstance(v, bool),
}
_SCHEMA_SAFE_DEFAULT = {"object": {}, "array": [], "string": "", "null": None}


# 2026-08-31 추가 — STEP9 사고(system_sections가 문자열로 와서 []로 대체됐는데, 사소한
# 보정과 똑같은 "⚠ 경고"로만 찍혀 심각도가 안 드러남) 대응. 이 필드들은 리포트의 실제
# 해석 내용을 담는 최상위 구조라, 통째로 빈 기본값으로 대체되면 손님이 낸 돈만큼의
# 내용이 그 자리에서 사라진다는 뜻 — 그래서 이 필드들에서 발생하는 정규화는 다른 사소한
# 보정(예: 하위 필드 하나가 비어서 ""로 채워짐)과 구분해 CRITICAL로 표시한다.
CRITICAL_TOP_LEVEL_FIELDS = frozenset({
    "system_sections", "cross_analysis", "opportunities", "risks",
    "action_plan", "question_answers", "long_term_strategy",
    # 2026-09-01 추가 — #3(D-2). new_reference_systems도 system_sections와 같은 급의
    # 최상위 구조 데이터(신규5개 시스템 내용)라 손실 시 같은 심각도로 다뤄야 한다.
    "new_reference_systems",
})


def _correction_severity(path):
    """path가 "report.<field>" 형태의 최상위 구조 필드를 가리키면 CRITICAL, 그 외
    (하위 필드 하나, 배열 원소 안쪽 등)는 MINOR — 손실 범위가 다르므로 구분한다."""
    parts = path.split(".")
    if len(parts) == 2 and parts[0] == "report" and parts[1] in CRITICAL_TOP_LEVEL_FIELDS:
        return "CRITICAL"
    return "MINOR"


def normalize_to_schema(value, schema, path, corrections):
    """2026-08-24 추가 — 실제로 두 번 연속 겪은 사고(action_plan이 dict 대신 문자열로,
    question_answers 항목이 dict 대신 문자열로 옴)를 계기로 만든 근본 수정. Anthropic
    구조화 출력이 스키마를 강제한다고 알려져 있지만 실전에서 타입이 어긋나는 사례가
    실제로 나왔고, 그때마다 이걸 나중에 건드리는 함수(check_hallucination만이 아니라
    report_kit.py의 PDF 렌더링까지)를 하나하나 방어 코드로 땜질하면 다음에 또 다른
    필드에서 같은 사고가 난다 — 그래서 "LLM 응답을 받는 그 즉시, 딱 한 곳에서" 스키마와
    실제 타입을 대조해 안전한 기본값으로 되돌리는 이 함수를 만들었다. 이후로는
    check_hallucination이든 report_kit.py든 전부 이미 정규화된 안전한 데이터만 보게 된다.
    무엇을 고쳤는지는 전부 corrections 리스트에 {"path","severity","message"} 딕셔너리로
    남겨 화면에 경고로 띄운다(내용이 조용히 사라지면 안 되므로) — 코드가 안 죽는 것과,
    손님에게 나갈 리포트에 구멍이 난 걸 사람이 아는 것은 별개다.

    2026-08-31 추가 — 이 함수는 여기서 절대 "문자열을 억지로 배열/객체로 추측 변환"하지
    않는다(1번 규칙과 같은 이유 — 애매한 추측으로 잘못된 내용을 끼워넣지 않음). 유일한
    복구 시도는 "정말로 같은 내용이 JSON 문자열로 이중 인코딩된 경우"뿐이고, 그마저
    실패하면 안전한 빈 기본값으로 대체하며 CRITICAL로 표시한다 — 오류를 숨기는 게
    아니라 원본 보존(main()의 raw 백업)과 명확한 손실 감지가 목적이다."""
    types = schema.get("type")
    if types is None:
        return value
    if isinstance(types, str):
        types = [types]

    if not any(_SCHEMA_TYPE_CHECK.get(t, lambda v: False)(value) for t in types):
        # 2026-08-24 추가 — 실제 사고 원인 확인: object/array가 와야 할 자리에 문자열이
        # 왔는데, 그 문자열 내용을 열어보니 원래 의도된 JSON이 그대로 들어있었다(모델이
        # 이 필드 전체를 이중으로 문자열 인코딩한 경우). 이럴 땐 버리지 않고 다시 파싱을
        # 시도한다 — 파싱이 깨끗이 성공할 때만 쓰고, 실패하면(예: 문장 안 인용부호를
        # 이스케이프 안 해서 JSON이 실제로 깨진 경우) 안전한 기본값으로만 대체한다 —
        # 애매하게 복구를 "추측"해서 잘못된 내용을 조용히 끼워넣느니, 차라리 그 부분만
        # 비워두는 쪽이 안전하다(이 프로젝트의 "지어내지 않는다" 원칙과 같은 이유).
        if isinstance(value, str) and ("object" in types or "array" in types):
            try:
                reparsed = json.loads(value)
                if any(_SCHEMA_TYPE_CHECK.get(t, lambda v: False)(reparsed) for t in types):
                    corrections.append({
                        "path": path, "severity": "MINOR",
                        "message": f"{path}: 문자열로 이중 인코딩되어 있던 걸 재파싱으로 복구함",
                    })
                    value = reparsed
                    types = [t for t in types if _SCHEMA_TYPE_CHECK[t](value)]
            except (json.JSONDecodeError, TypeError):
                pass
        if not any(_SCHEMA_TYPE_CHECK.get(t, lambda v: False)(value) for t in types):
            default = next((_SCHEMA_SAFE_DEFAULT[t] for t in types if t in _SCHEMA_SAFE_DEFAULT), None)
            corrections.append({
                "path": path, "severity": _correction_severity(path),
                "message": f"{path}: 예상 타입({'/'.join(types)})이 아님(실제: {type(value).__name__}) → {default!r}로 대체",
            })
            return default

    if isinstance(value, dict) and "properties" in schema:
        result = dict(value)
        for key, sub_schema in schema["properties"].items():
            if key in result:
                result[key] = normalize_to_schema(result[key], sub_schema, f"{path}.{key}", corrections)
        # 2026-08-29 추가 — 실제 사고: cross_analysis.heading이 응답에서 통째로 빠진 채
        # 왔는데, 위 루프는 "이미 있는 키의 타입"만 검사해서 이 누락을 못 잡았다
        # (report_kit.py가 안전장치 없이 그 키를 직접 읽다가 KeyError로 죽어, 이미 돈을
        # 낸 리포트가 PDF 변환 단계에서 통째로 날아갈 뻔했다 — 80회 시뮬레이션에서 재현
        # 확인). "이미 있는 데이터의 타입만 정규화"에서 "필수 필드가 아예 없어도 채운다"로
        # 넓힌다 — required로 지정된 키가 응답에 없으면 안전한 기본값으로 채워 넣는다.
        for key in schema.get("required", []):
            if key not in result:
                key_schema = schema["properties"].get(key, {})
                key_types = key_schema.get("type")
                if isinstance(key_types, str):
                    key_types = [key_types]
                default = next((_SCHEMA_SAFE_DEFAULT[t] for t in (key_types or []) if t in _SCHEMA_SAFE_DEFAULT), None)
                sub_path = f"{path}.{key}"
                corrections.append({
                    "path": sub_path, "severity": _correction_severity(sub_path),
                    "message": f"{sub_path}: 필수 필드가 응답에 아예 없음 → {default!r}로 채움",
                })
                result[key] = default
        return result

    if isinstance(value, list) and "items" in schema:
        return [normalize_to_schema(item, schema["items"], f"{path}[{i}]", corrections) for i, item in enumerate(value)]

    return value


_TIER_REQUIRED_NEW_SYSTEMS = {
    "dual": ["tojeong"],
    "master": ["tojeong", "yukhyo"],
    "premium": ["tojeong", "yukhyo", "seongmyeonghak", "pungsu", "taekil"],
}


def _build_tojeong_section(computed):
    tj = (computed.get("saju") or {}).get("tojeong")
    if not tj:
        return None
    g = tj["gwae"]
    body = (
        f"{tj['target_year']}년 토정비결은 {g['code']}괘입니다. "
        f"상괘는 {g['sang_meaning']['name']}로, {g['sang_meaning']['meaning']} "
        f"{g['jung_meaning']} {g['ha_meaning']} "
        f"{(computed.get('saju') or {}).get('tojeong', {}).get('methodology_note', '')}"
    ).strip()
    return {"system": "tojeong", "heading": f"{tj['target_year']}년 토정비결 — {g['code']}괘",
            "body": body, "key_insight": g["sang_meaning"]["meaning"], "takeaways": []}


def _build_yukhyo_section(computed):
    yh = (computed.get("saju") or {}).get("yukhyo")
    if not yh:
        return None
    bg = yh["bon_gwae"]
    body = (
        f"지금 이 순간 뽑아본 괘의 하괘는 {bg['ha_meaning']['name']}, 상괘는 {bg['sang_meaning']['name']}입니다. "
        f"{bg['ha_meaning']['meaning']} {bg['sang_meaning']['meaning']}"
    )
    jg = yh.get("ji_gwae")
    if jg:
        body += (
            f" 변효가 있어 지괘도 함께 나왔습니다 — 지금은 이렇지만 변화가 있다면 "
            f"{jg['ha_meaning']['name']}과 {jg['sang_meaning']['name']} 쪽으로 흘러갈 수 있습니다."
        )
    else:
        body += " 변효 없이 지금 상태가 그대로 유지되는 흐름입니다."
    body += " " + (yh.get("methodology_note") or "")
    return {"system": "yukhyo", "heading": "육효ㆍ주역 — 지금 이 순간의 괘",
            "body": body.strip(), "key_insight": bg["sang_meaning"]["meaning"], "takeaways": []}


def _build_seongmyeonghak_section(computed):
    sm = (computed.get("saju") or {}).get("seongmyeonghak")
    if not sm:
        return None
    letters = "ㆍ".join(f"{l['char']}({l['oheng']})" for l in sm.get("letters") or [])
    pairs = " ".join(f"{p['from']}→{p['to']}: {p['relation']}." for p in sm.get("pairs") or [])
    body = f"{sm.get('name')}의 발음오행은 {letters}입니다. {pairs} {sm.get('flow_summary') or ''} {sm.get('methodology_note') or ''}"
    return {"system": "seongmyeonghak", "heading": "성명학 — 이름의 발음오행",
            "body": body.strip(), "key_insight": sm.get("flow_summary") or "", "takeaways": []}


def _build_pungsu_section(computed):
    pu = (computed.get("saju") or {}).get("pungsu")
    if not pu:
        return None
    parts = []
    for rec in pu.get("recommendations") or []:
        spaces = "ㆍ".join(s["label"] for s in rec.get("spaces") or [])
        parts.append(f"부족한 {rec['oheng']} 기운은 {rec['color']}과 {rec['direction']} 방향으로 보완할 수 있고, {spaces} 같은 공간에 적용해보시면 좋습니다.")
    parts.extend(pu.get("dominant_note") or [])
    body = " ".join(parts) + " " + (pu.get("methodology_note") or "")
    return {"system": "pungsu", "heading": "풍수지리 — 생활 속 오행 배치",
            "body": body.strip(), "key_insight": (parts[0] if parts else ""), "takeaways": []}


def _build_taekil_section(computed):
    tk = (computed.get("saju") or {}).get("taekil")
    if not tk:
        return None
    good = tk.get("good_days") or []
    avoid = tk.get("avoid_days") or []
    body = f"앞으로 {tk.get('range_days')}일 중 {len(good)}일이 특히 힘이 되는 날, {len(avoid)}일이 피하면 좋은 날로 나타납니다."
    if good:
        body += f" 예를 들어 {good[0]['date']}은 {good[0]['reason']}입니다."
    if avoid:
        body += f" 반대로 {avoid[0]['date']}은 {avoid[0]['reason']}입니다."
    body += " " + (tk.get("methodology_note") or "")
    body = body.strip()
    # 2026-08-29 수정 — 실제 사고 발견(사용자 검수): key_insight를 body[:60]으로 그냥
    # 잘라서 "예를 들어 2026-09"처럼 날짜 중간에서 끊긴 문장이 "한눈에 보기"ㆍ챕터
    # 인용구에 그대로 노출됐다. 문장 경계를 아는 _find_first_sentence()를 재사용해
    # 항상 완결된 문장만 key_insight로 쓴다.
    key_insight = _find_first_sentence(body) or body[:60]
    return {"system": "taekil", "heading": "택일 — 앞으로 30일 참고",
            "body": body, "key_insight": key_insight, "takeaways": []}


_NEW_SYSTEM_BUILDERS = {
    "tojeong": _build_tojeong_section, "yukhyo": _build_yukhyo_section,
    "seongmyeonghak": _build_seongmyeonghak_section, "pungsu": _build_pungsu_section,
    "taekil": _build_taekil_section,
}

_NEW5_SYSTEM_KEYS = ("tojeong", "yukhyo", "seongmyeonghak", "pungsu", "taekil")


def _has_new5_body_content(obj):
    """system_sections 항목이든 new_reference_systems[key] 값이든, 실제 본문이 있는지
    같은 기준(body 10자 이상)으로 판단 — ensure_required_new_engine_sections()의
    기존 _has_content()와 동일한 임계값(2026-08-30 도입 이유도 동일: 태그만 있고
    본문이 비어있는 걸 "있다"고 오판하지 않기 위함)."""
    return isinstance(obj, dict) and isinstance(obj.get("body"), str) and len(obj.get("body").strip()) >= 10


def _merge_new_reference_systems_into_sections(report):
    """2026-09-01 추가 — #3(D-2). new_reference_systems(dict key 기반)에 LLM이 채운
    내용을 system_sections(배열) 항목 모양으로 변환해 병합한다.

    이 함수 이후로는 ensure_required_new_engine_sections()를 포함한 모든 하위 로직이
    지금까지와 똑같이 system_sections 하나만 보면 된다(report_kit.py PDF 렌더러도
    변경 없음) — new_reference_systems는 이 함수 안에서만 소비되는 입력 채널.

    두 경로 동시 존재 시 중복 생성 방지: system_sections에 이미 같은 system 태그로
    유효한 콘텐츠(_has_new5_body_content)가 있으면(LLM이 예전 방식대로 직접 썼거나,
    이 함수가 이미 병합해둔 경우) new_reference_systems 쪽 값은 무시하고 건너뛴다."""
    nrs = report.get("new_reference_systems")
    if not isinstance(nrs, dict):
        return
    sections = report.get("system_sections")
    if not isinstance(sections, list):
        return

    existing_tags = {
        s.get("system") for s in sections
        if isinstance(s, dict) and _has_new5_body_content(s)
    }
    for key in _NEW5_SYSTEM_KEYS:
        if key in existing_tags:
            continue  # system_sections 쪽에 이미 유효 콘텐츠 존재 — 중복 생성 금지
        entry = nrs.get(key)
        if not _has_new5_body_content(entry):
            continue
        sections.append({
            "system": key,
            "heading": entry.get("heading") or "",
            "body": entry.get("body") or "",
            "key_insight": entry.get("key_insight") or "",
            "takeaways": entry.get("takeaways") or [],
        })


def ensure_required_new_engine_sections(report, computed):
    """2026-08-29 추가 — check_required_tier_sections()는 신규 5개 시스템 섹션이
    빠진 걸 경고만 했는데, 사용자 지적: "안다고 방치할 수는 없다ㆍ덮어쓴다고 원인이
    사라지지 않는다." 발송을 막는 게이트를 다는 것도 결국 감지일 뿐 생성 자체를
    고치는 게 아니다 — ensure_emphasis/ensure_term_glosses와 완전히 같은 원칙을
    여기도 적용한다: **LLM이 안 써도 코드가 computed.json의 실제 계산값으로 그
    섹션을 직접 조립해 채운다.** 새 텍스트를 지어내는 게 아니라 이미 계산된 진짜
    데이터(gwae 뜻풀이ㆍ발음오행ㆍ풍수 추천ㆍ택일 길흉일)를 문장으로 엮는 것뿐이라
    1번 규칙(지어내지 않기)을 그대로 지킨다 — {{용어}} 자동 치환과 동일한 성격.
    LLM이 이미 그 시스템을 다뤘으면(system 태그로 확인) 손대지 않는다."""
    tier = computed.get("tier")
    required = _TIER_REQUIRED_NEW_SYSTEMS.get(tier)
    if not required:
        return

    sections = report.get("system_sections")
    if not isinstance(sections, list):
        return

    def _has_content(sec):
        # 2026-08-30 추가 — 지금까지는 system 태그만 있으면 "이미 다뤘다"고 보고 건너
        # 뛰었는데, 그러면 모델이 스키마의 required(system/heading/body)만 만족시키려
        # body를 빈 문자열(또는 공백)로만 채워도 이 함수가 진짜 데이터로 채우는 걸
        # 영구히 건너뛴다 — "태그가 있다"와 "내용이 실제로 있다"는 다르다.
        return isinstance(sec, dict) and isinstance(sec.get("body"), str) and len(sec.get("body").strip()) >= 10

    systems_present = {s.get("system") for s in sections if _has_content(s)}

    added = []
    for key in required:
        if key in systems_present:
            continue
        builder = _NEW_SYSTEM_BUILDERS.get(key)
        sec = builder(computed) if builder else None
        if sec:
            # 내용 없이 태그만 있던 기존 항목이 있으면 빼고 교체 — 빈 섹션과 방금
            # 조립한 진짜 섹션이 나란히 중복 등장하는 걸 막는다.
            sections[:] = [s for s in sections if not (isinstance(s, dict) and s.get("system") == key)]
            sections.append(sec)
            added.append(key)

    if added:
        print(f"✓ 신규 참고 시스템 섹션 자동 보강 완료({', '.join(added)} — computed.json 실제 값으로 직접 조립)")


_KOREAN_COUNT_WORDS = {"한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10}
_MAJOR_ARCANA_PREFIX_RE = re.compile(r"^\d+\.\s")


def ensure_tarot_suit_tally(report, computed):
    """근본 수정 — check_tarot_suit_tally가 잡아내는 "LLM이 카드 계열 개수를 잘못
    세서 문장에 씀" 문제를 경고만 하고 두지 않고, 실제 computed.json 값으로 본문
    문장의 한글 수사를 직접 고쳐 쓴다. 숫자 하나만 정답으로 치환하는 순수 기계적
    교정이라 문장 훼손 위험이 없다(check_term_glosses류의 ensure_* 패턴과 동일)."""
    def _l(v):
        return v if isinstance(v, list) else []

    draws = _l((computed.get("tarot") or {}).get("draws"))
    if not draws:
        return

    real_counts = {"완드": 0, "소드": 0, "컵": 0, "펜타클": 0, "메이저": 0}
    for d in draws:
        name = str((d or {}).get("card_name") or "")
        if name.startswith("완드"):
            real_counts["완드"] += 1
        elif name.startswith("소드"):
            real_counts["소드"] += 1
        elif name.startswith("컵"):
            real_counts["컵"] += 1
        elif name.startswith("펜타클"):
            real_counts["펜타클"] += 1
        elif _MAJOR_ARCANA_PREFIX_RE.match(name):
            real_counts["메이저"] += 1

    count_word_alt = "|".join(_KOREAN_COUNT_WORDS.keys())
    real_word = {v: k for k, v in _KOREAN_COUNT_WORDS.items()}

    for sec in _l(report.get("system_sections")):
        if not (isinstance(sec, dict) and sec.get("system") == "tarot"):
            continue
        body = str(sec.get("body") or "")
        if not body:
            continue

        def _fix(m):
            suit, word = m.group(1), m.group(2)
            real_n = real_counts.get(suit, 0)
            if real_n and real_n in real_word and _KOREAN_COUNT_WORDS.get(word) != real_n:
                start = m.start(2) - m.start(0)
                end = m.end(2) - m.start(0)
                return m.group(0)[:start] + real_word[real_n] + m.group(0)[end:]
            return m.group(0)

        sec["body"] = re.sub(
            rf"(완드|소드|컵|펜타클|메이저)\s*(?:계열이|카드가)\s*({count_word_alt})\s*장",
            _fix,
            body,
        )


def check_tarot_suit_tally(report, computed):
    """2026-08-29 추가 — 사용자 검수로 실제 발견: 실제 발송된 리포트에서 열 장 중
    완드3ㆍ소드2ㆍ컵2ㆍ메이저3이 진짜 계산값인데, 본문 총론 문장은 "소드 계열이 세
    장ㆍ메이저 카드가 두 장"이라고 잘못 집계해서 썼다(LLM의 산수 실수, 카드 자체는
    안 지어냈으니 check_hallucination()이 안 걸러짐 — 그건 "있는 카드인가"만 보지
    "개수를 정확히 셌는가"는 안 보기 때문). computed.json의 실제 draws에서 계열별
    개수를 코드로 직접 세서, 본문에 쓰인 "~계열이 O 장" 문장의 숫자(한글 수사)와
    대조한다 — 판단이 필요 없는 순수 산수 대조라 여기서 기계적으로 처리(check_term_
    glosses와 같은 성격). 문장 패턴을 못 찾으면(다른 표현으로 썼을 수 있음) 조용히
    건너뛴다 — 별자리 검사와 같은 이유로 완벽한 검사가 아니라 신호일 뿐."""
    def _l(v):
        return v if isinstance(v, list) else []

    draws = _l((computed.get("tarot") or {}).get("draws"))
    if not draws:
        return

    real_counts = {"완드": 0, "소드": 0, "컵": 0, "펜타클": 0, "메이저": 0}
    for d in draws:
        name = str((d or {}).get("card_name") or "")
        if name.startswith("완드"):
            real_counts["완드"] += 1
        elif name.startswith("소드"):
            real_counts["소드"] += 1
        elif name.startswith("컵"):
            real_counts["컵"] += 1
        elif name.startswith("펜타클"):
            real_counts["펜타클"] += 1
        elif _MAJOR_ARCANA_PREFIX_RE.match(name):
            real_counts["메이저"] += 1

    all_text = "".join(
        str((sec or {}).get("body") or "")
        for sec in _l(report.get("system_sections"))
        if isinstance(sec, dict) and sec.get("system") == "tarot"
    )
    if not all_text:
        return

    count_word_alt = "|".join(_KOREAN_COUNT_WORDS.keys())
    problems = []
    for suit, real_n in real_counts.items():
        if real_n == 0:
            continue
        m = re.search(rf"{suit}\s*(?:계열이|카드가)\s*({count_word_alt})\s*장", all_text)
        if m and _KOREAN_COUNT_WORDS[m.group(1)] != real_n:
            problems.append(f"{suit}: 실제로는 {real_n}장인데 본문은 '{m.group(1)} 장'이라고 씀")

    if problems:
        print("⚠ 경고: 타로 카드 계열 개수가 실제 계산값과 다름(LLM 집계 오류 가능성) — 발송 전 확인할 것:")
        for p in problems:
            print(f"    - {p}")
    else:
        print("✓ 타로 카드 계열 개수 검사 통과(문장 패턴 발견 시에만 대조, 완벽하지 않음)")


_WS_RE = re.compile(r"\s+")


def _normalize_ws(s):
    return _WS_RE.sub(" ", str(s or "")).strip()


def check_qa_count_and_order(report, computed):
    """2026-08-30 추가 — LLM→PDF 신뢰성 프로토콜 문서 검토 중 발견: 고객이 실제로
    낸 질문 개수(computed["customer"]["questions"])와 report["question_answers"]의
    개수ㆍ순서가 일치하는지 대조하는 코드가 이 프로젝트에 하나도 없었다(grep 0건
    확인). SYSTEM_PROMPT 10번 규칙("질문 개수만큼 정확히, 빠뜨리거나 합치지
    말 것")을 LLM이 지킬 거라는 믿음에만 의존하고 있었다 — 지금까지 우연히 한 번도
    안 터졌을 뿐, 코드 검증은 전혀 없었다.

    LLM이 질문을 답변에 옮길 때 줄바꿈(\\r\\n)을 공백으로 펴서 약간 다르게 옮기는
    걸 실제 리포트에서 확인했으므로(정상적인 재구성), 완전 일치가 아니라 공백
    정규화 후 대조한다. 값을 지어낼 방법이 없는 순수 대조라 check_tarot_suit_tally와
    같은 성격 — 경고만 하고 자동 수정은 하지 않는다(질문이 빠졌다면 코드가 안전하게
    새 답을 지어낼 수 없으므로 사람ㆍLLM 재작성이 필요한 영역)."""
    raw_questions = ((computed.get("customer") or {}).get("questions")) or []
    if not isinstance(raw_questions, list) or not raw_questions:
        return
    qa_list = report.get("question_answers")
    if not isinstance(qa_list, list):
        print(f"⚠ 경고: 고객이 질문 {len(raw_questions)}개를 냈는데 question_answers 자체가 없음 — 발송 전 확인할 것")
        return

    problems = []
    if len(raw_questions) != len(qa_list):
        problems.append(f"질문 {len(raw_questions)}개를 냈는데 답변은 {len(qa_list)}개임(개수 불일치)")

    norm_raw = [_normalize_ws(q) for q in raw_questions]
    norm_qa = [_normalize_ws((qa or {}).get("question")) for qa in qa_list if isinstance(qa, dict)]
    for i, rq in enumerate(norm_raw):
        if i >= len(norm_qa):
            problems.append(f"{i+1}번째 질문({rq[:30]}...)에 대응하는 답변 항목 자체가 없음")
            continue
        aq = norm_qa[i]
        # 완전 일치는 요구하지 않는다(모델이 줄바꿈을 공백으로 펴는 정상적인 재구성은
        # 허용) — 대신 앞부분이 상당 부분 겹치는지만 본다. 안 겹치면 순서가 섞였거나
        # 질문이 통째로 바뀐 것.
        if rq[:15] not in aq and aq[:15] not in rq:
            # 다른 위치에 이 질문이 있는지 찾아 "순서만 바뀜"과 "질문 자체가 사라짐"을 구분
            found_elsewhere = any(rq[:15] in other or other[:15] in rq for j, other in enumerate(norm_qa) if j != i)
            if found_elsewhere:
                problems.append(f"{i+1}번째 질문이 답변 순서상 다른 자리로 밀려남(순서 불일치): {rq[:30]}...")
            else:
                problems.append(f"{i+1}번째 질문이 답변 목록 어디에도 안 보임(질문 누락 가능성): {rq[:30]}...")

    if problems:
        print("⚠ 경고: 질문-답변 개수ㆍ순서 불일치 — 발송 전 반드시 확인할 것:")
        for p in problems:
            print(f"    - {p}")
    else:
        print(f"✓ 질문-답변 개수ㆍ순서 검사 통과({len(raw_questions)}개 모두 순서대로 대응됨)")


_LEFTOVER_PATTERNS = ["TODO", "FIXME", "DEBUG", "PLACEHOLDER", "{{", "}}", "여기에 입력", "lorem ipsum", "Lorem ipsum"]


def check_leftover_placeholders(report):
    """2026-08-30 추가 — LLM→PDF 신뢰성 프로토콜 문서 검토 중 발견: TODOㆍFIXMEㆍ
    DEBUGㆍ남은 `{{}}` 표시 같은 잔재 문자열을 검색하는 코드가 이 프로젝트에 전혀
    없었다(grep 0건 확인). expand_term_placeholders()가 사전에 없는 용어까지도
    중괄호를 벗기게 되어 있어 `{{}}`가 최종 문서에 남을 가능성은 이미 낮지만, 그건
    "그 함수가 항상 완벽히 호출된다"는 가정에 의존하는 것이라 별도의 마지막 안전망을
    둔다 — 순수 문자열 검색이라 판단이 필요 없고 실수로 놓칠 이유가 없다."""
    hits = []

    def _walk(obj, path):
        if isinstance(obj, str):
            for pat in _LEFTOVER_PATTERNS:
                if pat in obj:
                    hits.append((path, pat))
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                _walk(v, f"{path}[{i}]")
        elif isinstance(obj, dict):
            for k, v in obj.items():
                _walk(v, f"{path}.{k}")

    _walk(report, "report")
    if hits:
        print("⚠ 경고: 남은 placeholder/디버그 문구 발견 — 발송 전 확인할 것:")
        for path, pat in hits:
            print(f"    - {path}: {pat!r}")
    else:
        print("✓ placeholder/디버그 문구 잔재 검사 통과")


_ASPECT_TYPE_WORDS = {
    "합(컨정션)": ["합"],
    "대립(오퍼지션)": ["대립", "오퍼지션"],
    "삼각(트라인)": ["삼각", "트라인"],
    "사각(스퀘어)": ["사각", "스퀘어"],
    "육각(섹스타일)": ["육각", "섹스타일"],
}
_ALL_ASPECT_WORDS = sorted({w for words in _ASPECT_TYPE_WORDS.values() for w in words}, key=len, reverse=True)
_HANGUL_RE = re.compile(r"[가-힣]")


def _aspect_word_present(word, window):
    for m in re.finditer(re.escape(word), window):
        if word == "합":
            # 2026-08-30 수정 — 실제 오탐 발견: "눈여겨볼 만합니다"의 "만합니다"에서
            # "합"만 걸려서 금성-목성이 실제론 사각(스퀘어)인데 "합"으로 잘못
            # 표현됐다고 오판했다("합"은 워낙 흔한 한글 음절이라 다른 단어 중간에도
            # 수시로 나타남). 바로 앞 글자가 한글 음절이면(그 단어의 일부일 뿐이면)
            # 무시하고, 공백ㆍ조사 경계처럼 새 단어로 시작하는 경우만 인정한다.
            before = window[m.start() - 1] if m.start() > 0 else " "
            if _HANGUL_RE.match(before):
                continue
        return True
    return False


def check_aspect_consistency(report, computed):
    """2026-08-30 추가 — QA 파이프라인 문서 검토 중 이번 세션에서 실제로 손으로
    한 번 검증한 것(리뷰어가 "금성-토성/천왕성은 스퀘어여야 한다"고 주장했는데 절대
    도수로 직접 계산해 틀렸음을 확인함)을 영구적인 자동 검사로 만든다. computed.
    astrology.aspects에 이미 engine이 계산한 실제 타입이 있으므로(재계산 불필요),
    본문에서 두 행성명이 가까이 언급되며 어스펙트 단어가 함께 쓰인 자리를 찾아
    실제 타입과 대조한다.

    2026-08-30 수정 — 실제 오탐 발견: 같은 두 행성이 본문 여러 자리에서 언급될 때
    "처음 찾은 자리 하나만" 보고 멈췄더니, 마침 그 첫 자리엔 아무 관계 설명이 없고
    (예: 단순히 좌표만 나열하는 문장) 두 번째 자리에 정확한 표현("목성과 금성 사이에
    사각(스퀘어) 관계")이 있는데도 그걸 못 보고 지나간 채 앞의 약한 오탐만 보고
    FAIL로 판정했다. 이제 이 쌍이 언급된 모든 자리를 다 보고, 그중 하나라도 정확한
    표현이 있으면 통과시킨다(다른 자리의 표현이 다소 부정확해도, 정확한 설명이
    최소 한 번 있으면 손님에게 잘못된 정보가 전달되는 게 아니므로).

    check_tarot_suit_tally와 같은 성격(문장 패턴을 찾았을 때만 대조, 완벽하지
    않음) — "삼각관계"처럼 어스펙트와 무관한 일반 표현이 드물게 오탐될 수 있으나
    경고만 할 뿐 자동 수정은 안 하므로 위험이 낮다."""
    aspects = ((computed.get("astrology") or {}).get("aspects")) or []
    if not aspects:
        return

    texts = []
    for sec in (report.get("system_sections") or []):
        if isinstance(sec, dict) and sec.get("system") == "astrology":
            texts.append(str(sec.get("body") or ""))
            texts.append(str(sec.get("key_insight") or ""))
    ca = report.get("cross_analysis")
    if isinstance(ca, dict):
        texts.append(str(ca.get("body") or ""))
    full_text = "\n".join(t for t in texts if t)
    if not full_text.strip():
        return

    problems = []
    checked_pairs = set()
    for asp in aspects:
        b1, b2, real_type = asp.get("body1"), asp.get("body2"), asp.get("type")
        if not (b1 and b2 and real_type):
            continue
        pair_key = frozenset((b1, b2))
        if pair_key in checked_pairs:
            continue
        real_words = _ASPECT_TYPE_WORDS.get(real_type, [])
        saw_any_mention = False
        saw_correct = False
        wrong_examples = []
        for m in re.finditer(re.escape(b1), full_text):
            window = full_text[max(0, m.start() - 60): m.start() + 60]
            if b2 not in window:
                continue
            mentioned = [w for w in _ALL_ASPECT_WORDS if _aspect_word_present(w, window)]
            if not mentioned:
                continue
            saw_any_mention = True
            if any(w in real_words for w in mentioned):
                saw_correct = True
                break  # 정확한 표현을 이미 찾았으니 이 쌍은 더 볼 필요 없음
            wrong_examples.append(mentioned)
        if saw_any_mention:
            checked_pairs.add(pair_key)
            if not saw_correct:
                problems.append(f"{b1}-{b2}: 실제로는 {real_type}인데 본문엔 {wrong_examples[0]}로만 표현됨")

    if problems:
        print("⚠ 경고: 어스펙트 명칭이 실제 계산값과 다름 — 발송 전 확인할 것:")
        for p in problems:
            print(f"    - {p}")
    else:
        print("✓ 어스펙트 명칭 검사 통과(문장 패턴 발견 시에만 대조, 완벽하지 않음)")


_OVERCLAIM_TOPICS = {
    "건강/질병": ["질병", "암입니다", "건강이 나빠질 것", "반드시 아프", "확실히 병"],
    "임신/자녀 성별": ["아들입니다", "딸입니다", "남자아이입니다", "여자아이입니다", "임신할 것입니다", "임신하게 됩니다"],
    "로또/복권": ["당첨됩니다", "당첨될 것입니다", "1등이 될 것"],
    "사망": ["사망할 것", "죽을 것", "명을 다할 시점"],
    "법적 결과": ["승소할 것입니다", "패소할 것입니다", "무죄가 될 것"],
    "투자 수익": ["수익이 날 것입니다", "반드시 오릅니다", "손실 없이"],
}


def check_overclaim_topics(report):
    """2026-08-30 추가 — QA 파이프라인/LLM→PDF 신뢰성 문서 둘 다 지적한 항목:
    건강ㆍ임신ㆍ자녀 성별ㆍ로또ㆍ사망ㆍ법적 결과ㆍ투자 수익처럼, 이 서비스가
    확정적으로 말하면 실제 법적ㆍ신뢰 리스크가 되는 주제에서 단정적 표현을 썼는지
    검사한다. check_unanswerable_reason_tone과 다른 문제(그건 "컴퓨터 말투",
    이건 "의료ㆍ법률 자문처럼 들리는 확정적 발언")라 별도 목록으로 둔다. 표현을
    코드가 안전하게 다시 쓸 방법은 없으므로(문장 재구성 필요) 경고만 한다."""
    def _l(v):
        return v if isinstance(v, list) else []

    texts = []
    for sec in _l(report.get("system_sections")):
        if isinstance(sec, dict):
            texts.append((f"system_sections[{sec.get('system')}]", str(sec.get("body") or "")))
    for qa in _l(report.get("question_answers")):
        if isinstance(qa, dict):
            texts.append((f"question_answers[{str(qa.get('question'))[:20]}]", str(qa.get("body") or "")))

    hits = []
    for label, text in texts:
        if not text:
            continue
        for topic, phrases in _OVERCLAIM_TOPICS.items():
            for phrase in phrases:
                if phrase in text:
                    hits.append((label, topic, phrase))

    if hits:
        print("⚠ 경고: 확정적 표현 금지 주제(건강ㆍ임신ㆍ로또ㆍ사망ㆍ법률ㆍ투자)에서 단정적 문구 발견 — 발송 전 확인할 것:")
        for label, topic, phrase in hits:
            print(f"    - {label} [{topic}]: {phrase!r}")
    else:
        print("✓ 확정적 표현(건강ㆍ임신ㆍ로또ㆍ사망ㆍ법률ㆍ투자) 검사 통과")


_QA_AVOIDANCE_PHRASES = [
    "계산하지 못했습니다", "계산할 수 없습니다", "말씀드리기 어렵습니다", "답변하기 어렵습니다",
    "답하기 어렵습니다", "알 수 없습니다", "확인할 수 없습니다", "판단할 수 없습니다",
    "판단하기 어렵습니다", "확정하기 어렵습니다", "알기 어렵습니다", "포함되어 있지 않습니다",
]


def check_qa_avoidance_ending(report):
    """2026-08-30 추가 — QA 파이프라인/LLM→PDF 신뢰성 문서 둘 다 강조한 항목(9-10번
    규칙 문서화 참고). check_unanswerable_reason_tone은 unanswerable_reason
    필드 하나만(컴퓨터 말투 4단어) 보는데, 이 검사는 question_answers 전체
    body를 대상으로 더 넓은 회피 표현 목록을 쓰고, "단어가 있다"가 아니라
    "답변이 그 표현으로 끝나는가"만 FAIL 후보로 본다(문서 12번 판정 기준과 동일 —
    회피 표현 뒤에 실질적 설명이 이어지면 정상적인 사용이므로 PASS)."""
    def _l(v):
        return v if isinstance(v, list) else []

    hits = []
    for qa in _l(report.get("question_answers")):
        if not isinstance(qa, dict):
            continue
        body = str(qa.get("body") or "").strip()
        if not body:
            continue
        for phrase in _QA_AVOIDANCE_PHRASES:
            if body.endswith(phrase) or body.endswith(phrase + "."):
                hits.append((qa.get("question"), phrase))
                break

    if hits:
        print("⚠ 경고: 회피형 표현으로 답변이 끝남(질문 거절 인상) — 발송 전 확인할 것:")
        for q, phrase in hits:
            print(f"    - {str(q)[:40]!r}: '...{phrase}'로 끝남")
    else:
        print("✓ Q&A 회피형 답변 종료 검사 통과")


def check_qa_duplicates_sections(report):
    """2026-08-30 추가 — 이전 검토(사용자 지적: 궁합 질문 답변이 궁합 system_section과
    거의 같은 문장)에서 나온 걸 기계적으로 대조하는 함수가 없었다. question_answers의
    각 body에서 문장 단위로 쪼개, system_sections의 아무 body에나 그대로(정규화한
    공백 기준) 들어있는 문장이 있으면 표시한다 — 완전 일치만 잡으므로(유사 표현은
    못 잡음) 과탐지 위험은 낮다."""
    def _l(v):
        return v if isinstance(v, list) else []

    section_sentences = set()
    for sec in _l(report.get("system_sections")):
        if not isinstance(sec, dict):
            continue
        body = str(sec.get("body") or "")
        for s in re.split(r"(?<=[.!?])\s+", body):
            s = _normalize_ws(s)
            if len(s) >= 20:  # 너무 짧은 문장은 우연히 겹칠 수 있어 제외
                section_sentences.add(s)

    if not section_sentences:
        return

    hits = []
    for qa in _l(report.get("question_answers")):
        if not isinstance(qa, dict):
            continue
        body = str(qa.get("body") or "")
        for s in re.split(r"(?<=[.!?])\s+", body):
            s = _normalize_ws(s)
            if len(s) >= 20 and s in section_sentences:
                hits.append((qa.get("question"), s))

    if hits:
        print("⚠ 경고: Q&A 답변이 system_sections 본문과 완전히 같은 문장을 복사함 — 발송 전 확인할 것:")
        for q, s in hits:
            print(f"    - {str(q)[:40]!r}: {s[:60]!r}")
    else:
        print("✓ Q&A ↔ system_sections 문장 복사 검사 통과")


def check_required_tier_sections(report, computed):
    """2026-08-29 추가 — 규칙(8번, 10-F-1번)을 정독하며 발견: 티어마다 "이 섹션은
    무조건 들어가야 한다"는 지시가 프롬프트에 상세히 있는데, 그게 실제로 지켜졌는지
    기계적으로 대조하는 코드가 지금까지 하나도 없었다. 오늘 밤 실제 프리미엄 리포트
    (최광호)에서 신규 시스템 5개가 통째로 빠진 사고도, 이런 검증이 없어서 아무도
    자동으로 못 잡고 손으로 파봐야만 드러났다 — check_term_glosses/check_emphasis_
    markers와 같은 성격의, 판단이 필요 없는 순수 구조 대조.

    경고만 남기고 발송은 막지 않는다(다른 check_* 함수들과 같은 원칙 — 아직 이
    검증 자체의 오탐 여부를 충분히 검증하지 못했으므로 하드 블록은 이르다)."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    tier = computed.get("tier")
    sections = _l(report.get("system_sections"))
    systems_present = {_d(s).get("system") for s in sections}
    problems = []

    if tier == "mini":
        if len(sections) != 1:
            problems.append(f"mini는 system_sections가 1개여야 하는데 {len(sections)}개임")
        if report.get("question_answers") is not None:
            problems.append("mini는 question_answers가 null이어야 함(질문을 안 받는 티어)")
        for f in ("cross_analysis", "long_term_strategy", "action_plan", "toc_preview"):
            if report.get(f) is not None:
                problems.append(f"mini는 {f}가 null이어야 함")

    elif tier == "light":
        if len(sections) < 2:
            problems.append(f"light는 system_sections가 최소 2개여야 하는데 {len(sections)}개임")

    else:
        # single/dual/master/premium 공통(8번 규칙 scope "full"/"premium")
        min_by_tier = {"single": 4, "dual": 8, "master": 11, "premium": 11}
        minimum = min_by_tier.get(tier)
        if minimum and len(sections) < minimum:
            problems.append(f"{tier}는 system_sections가 최소 {minimum}개여야 하는데 {len(sections)}개임")

        # 2026-08-31 추가 — STEP6 사고(#4): tarot 전용 섹션이 통째로 빠졌는데도 saju+
        # astrology+신규5개 합만으로 개수 기준(min_by_tier)을 넘겨 이 함수가 "통과"를
        # 찍은 걸 실제로 확인함 — 개수만 보고 "구매한 체계 각각의 존재"는 한 번도 검사한
        # 적이 없었다는 게 근본 원인. saju/astrology/tarot도 tojeong 등 5개와 동일하게
        # computed.json에 그 체계가 있으면 system_sections에도 반드시 있어야 한다.
        for core_system in ("saju", "astrology", "tarot"):
            if computed.get(core_system) and core_system not in systems_present:
                problems.append(f"{tier}는 computed.{core_system}이 있는데 {core_system} 전용 섹션이 없음")

        if tier in ("dual", "master", "premium") and "tojeong" not in systems_present:
            problems.append(f"{tier}는 saju.tojeong 전용 섹션이 반드시 있어야 하는데 없음(10-F-1번)")
        if tier in ("master", "premium") and "yukhyo" not in systems_present:
            problems.append(f"{tier}는 saju.yukhyo 전용 섹션이 반드시 있어야 하는데 없음(10-F-1번)")
        if tier == "premium":
            for sys_name in ("seongmyeonghak", "pungsu", "taekil"):
                if sys_name not in systems_present:
                    problems.append(f"premium은 saju.{sys_name} 전용 섹션이 반드시 있어야 하는데 없음(10-F-1번)")

        if tier == "dual" and report.get("cross_analysis") is None and computed.get("astrology"):
            problems.append("dual은 cross_analysis가 있어야 함(사주ㆍ점성술 교차검증)")
        if tier in ("master", "premium") and report.get("action_plan") is None:
            problems.append(f"{tier}는 action_plan이 있어야 함(9-B번)")
        if tier == "premium":
            lts = _d(report.get("long_term_strategy"))
            for f in ("decade_roadmap", "lifetime_design", "second_act"):
                if not _d(lts.get(f)).get("body"):
                    problems.append(f"premium은 long_term_strategy.{f}가 채워져야 함(9-A번)")

    # 궁합 — SINGLE 이상 전 티어, computed.json에 gunghap이 있으면 자동 포함(2026-08-23 규칙).
    # "system" enum에 gunghap 전용 값이 없어(saju로 태그됨) 휴리스틱으로 heading/body에
    # "궁합"이 있는지로 대조 — 완벽하지 않으니 다른 check_* 함수처럼 신호로만 쓴다.
    if tier not in ("mini", "light") and computed.get("saju") and computed.get("gunghap"):
        has_gunghap_section = any("궁합" in (str(_d(s).get("heading") or "") + str(_d(s).get("body") or ""))
                                   for s in sections)
        if not has_gunghap_section:
            problems.append(f"{tier}는 computed.gunghap이 있으면 궁합 전용 섹션이 있어야 함(2026-08-23 규칙)")

    if problems:
        print(f"⚠ 경고: 티어별 필수 섹션 규칙 위반 발견({tier}):")
        for p in problems:
            print(f"    - {p}")
    else:
        print(f"✓ 티어별 필수 섹션 검사 통과({tier})")


class ComputedContractError(RuntimeError):
    """2026-09-03 추가 — STEP2(computed contract 안정화). report.json(LLM 출력) 쪽에는
    normalize_to_schema()라는 정교한 타입 강제+손실 로깅 장치가 있는데, computed.json
    (JS 엔진 출력) 쪽에는 top-level 3개 시스템 존재 여부(enforce_purchased_core_systems_
    present) 외엔 검증이 전혀 없었다 — 나머지 전부 `.get(...) or {}` 체인으로만 소비돼,
    엔진 필드가 깨지거나 이름이 바뀌어도 코드가 죽지 않고 조용히 빈 값으로 흘러가는
    구조였다(2차/3차 감사에서 확인, 12운성 뜻풀이 오등록 실제 사고가 바로 이 비대칭
    때문에 한 번 발생했었음).

    이 예외는 "본문 생성ㆍ검증에 실제로 쓰이는 것으로 확인된" 핵심 필드
    (saju.pillars/saju.shensha/saju.correspondence.shi_shen_meanings)가 실제로 깨져
    있을 때만 발생한다 — astrology/tarot/tojeong 같은 tier별 optional system이
    없는 것은 정상이며 이 예외 대상이 아니다(enforce_computed_core_contract 참고).
    CoreSystemMissingError/ForbiddenTierSystemError와 동일한 하드블록 철학 — uncaught로
    전파돼 main()의 report.json 저장 전에 파이프라인을 멈추고 raw 백업을 자연스럽게
    보존한다. 단, 이 검증은 computed 로드 직후(call_llm 호출 전)에 실행해 애초에
    깨진 계산값으로 유료 API를 호출하는 낭비 자체를 막는다(CoreSystemMissingError보다
    이른 시점)."""


def enforce_computed_core_contract(computed):
    """computed.json의 핵심 계약 필드를 검증한다. 존재하지 않아야 할 optional system
    (astrology/tarot/tojeong/yukhyo 등, tier마다 다름)은 절대 건드리지 않는다 — saju
    자체는 이 프로젝트의 모든 tier에 공통으로 존재하는 핵심 시스템이므로(catalog.js
    전 tier 기준 확인), saju 및 그 아래 세 핵심 필드만 검증 대상이다.

    잘못된 값을 조용히 기본값으로 대체하지 않는다 — 깨져 있으면 그대로 예외를 던진다
    (report.json의 normalize_to_schema와 다른 지점: 저건 "LLM이 가끔 스키마를 어길 수
    있으니 안전하게 되돌린다"는 복구 장치이고, 이건 "우리가 만든 계산값 자체가 깨지면
    그건 원본 데이터 오류이니 감추지 말고 즉시 알아야 한다"는 하드블록이라 목적이
    다르다)."""
    if not isinstance(computed, dict):
        raise ComputedContractError("computed 자체가 dict가 아님 — 원본 JSON을 확인할 것")

    saju = computed.get("saju")
    if not isinstance(saju, dict):
        raise ComputedContractError("computed.saju가 없거나 dict가 아님(이 프로젝트의 모든 tier가 saju를 포함해야 함)")

    # --- pillars: saju.js computeSaju()의 pillars={year,month,day,hour} 계약.
    # hour는 unknown_time이면 의도적으로 None(saju.js:98) — None 자체는 정상, 구조가
    # 아예 다르거나 ganzhi_ko가 없는 경우만 계약 위반으로 본다.
    pillars = saju.get("pillars")
    if not isinstance(pillars, dict):
        raise ComputedContractError("computed.saju.pillars가 없거나 dict가 아님")
    for key in ("year", "month", "day"):
        p = pillars.get(key)
        if not isinstance(p, dict) or not p.get("ganzhi_ko"):
            raise ComputedContractError(f"computed.saju.pillars.{key}이 없거나 ganzhi_ko가 없음")
    hour = pillars.get("hour")
    if hour is not None and (not isinstance(hour, dict) or not hour.get("ganzhi_ko")):
        raise ComputedContractError("computed.saju.pillars.hour이 None(시간 미상)도 아니고 유효한 구조도 아님")

    # --- shensha: shensha.js computeShensha()의 taohua/yeokma/hwagae/hongyeom 계약.
    # "없음" 상태는 present:false로만 표현되고(key 자체가 빠지거나 null이 되는 경우는
    # 없음) — SHENSHA_KEY_TO_LABEL(기존 상수 재사용, 새로 만들지 않음)의 4개 키 전부
    # present(bool)+meaning(문자열)을 항상 가져야 한다.
    shensha = saju.get("shensha")
    if not isinstance(shensha, dict):
        raise ComputedContractError("computed.saju.shensha가 없거나 dict가 아님")
    for key in SHENSHA_KEY_TO_LABEL:
        entry = shensha.get(key)
        if not isinstance(entry, dict) or "present" not in entry or not entry.get("meaning"):
            raise ComputedContractError(
                f"computed.saju.shensha.{key} 구조가 깨짐(present/meaning이 있는 dict여야 함)"
            )

    # --- correspondence.shi_shen_meanings: correspondence.js buildCorrespondence()의
    # 계약. 이 손님의 실제 네 기둥에 등장한 십신만 담기므로 list 자체는 비어있을 수
    # 있다(빈 리스트는 정상) — 각 원소가 name을 가진 dict인지만 확인한다. meaning은
    # null일 수 있음(JS: SHI_SHEN_MEANING[s] || null)을 build_term_gloss_map()이 이미
    # 안전하게 처리하므로(항목 자체를 건너뜀) meaning까지 필수로 강제하지 않는다.
    correspondence = saju.get("correspondence")
    if not isinstance(correspondence, dict):
        raise ComputedContractError("computed.saju.correspondence가 없거나 dict가 아님")
    shi_shen_meanings = correspondence.get("shi_shen_meanings")
    if not isinstance(shi_shen_meanings, list):
        raise ComputedContractError("computed.saju.correspondence.shi_shen_meanings가 list가 아님")
    for item in shi_shen_meanings:
        if not isinstance(item, dict) or not item.get("name"):
            raise ComputedContractError(
                "computed.saju.correspondence.shi_shen_meanings의 항목 구조가 깨짐(name이 있는 dict여야 함)"
            )


class CoreSystemMissingError(RuntimeError):
    """2026-08-31 추가 — #4(타로 누락) 재발 방지. 구매한 핵심 체계(saju/astrology/
    tarot)가 system_sections에서 통째로 빠졌을 때 조용히 넘어가지 않고 파이프라인을
    여기서 완전히 멈춘다.

    신규5개 시스템처럼 코드가 computed.json 값을 f-string으로 대신 채우는 fallback을
    tarot에 만들지 않는다 — 타로 해석은 카드ㆍ계산값ㆍ손님 상황을 엮는 진짜 해석이
    필요해서, 미리 계산된 값을 그대로 나열하는 수준의 fallback을 만들면 "핵심 해석을
    코드 템플릿으로 대체"하게 되어 이전에 사용자가 명시적으로 금지한 원칙을 어기게
    된다. saju/astrology도 같은 이유로 fallback이 없다(지금까지 실제로 빠진 적이
    없었을 뿐, 빠지면 이 예외도 saju/astrology에 똑같이 적용된다).

    이 예외가 발생하면 report.json은 저장되지 않고(main()에서 이 호출 뒤에 저장
    로직이 있음), 파이프라인 끝의 raw_backup_path.unlink()도 실행되지 않아 raw
    원본이 자동으로 남는다 — 별도 보존 로직을 추가하지 않고 "예외가 전파되면 정리
    코드가 안 돈다"는 자연스러운 성질만으로 raw를 지킨다."""


def enforce_purchased_core_systems_present(report, computed):
    sections = report.get("system_sections")
    systems_present = (
        {s.get("system") for s in sections if isinstance(s, dict)}
        if isinstance(sections, list) else set()
    )
    missing = [
        system for system in ("saju", "astrology", "tarot")
        if computed.get(system) and system not in systems_present
    ]
    if missing:
        raise CoreSystemMissingError(
            f"구매한 핵심 체계가 system_sections에 전혀 없음: {missing} — "
            "이 리포트는 저장ㆍ발송하면 안 됨. raw 백업(정규화 전 원본)을 확인해 재처리할 것."
        )


class ForbiddenTierSystemError(RuntimeError):
    """2026-09-01 추가 — #16 dual 실제 API 검증에서 실제로 발생한 사고 대응. dual(10만원)
    고객에게 master(15만원) 전용 new_reference_systems.yukhyo가 LLM 자체 판단으로
    생성됨을 실제 API 응답에서 확인함 — 컴파일된 dual 프롬프트에 "MASTER 이상은 그에
    더해 yukhyo"라는 tier gating 문구가 명시돼 있었음에도 LLM이 이를 무시했다. 즉
    프롬프트 문구 문제가 아니라 결정론적 강제 장치의 부재가 근본 원인이었다(사용자 지시
    그대로).

    CoreSystemMissingError(필수 체계 누락, #4)와 반대 방향의 문제(금지 체계 과다 생성)
    지만, "이 예외가 전파되면 main()의 report.json 저장ㆍraw_backup_path.unlink()가
    자동으로 안 돈다"는 동일한 하드블록 메커니즘을 그대로 재사용한다(새 예외 처리 골격을
    따로 만들지 않음). 원인이 서로 다르므로 이름만 구분한다(원인 추적성ㆍCoreSystem
    MissingError와 혼동 방지) — 취급 방식(전파ㆍraw 보존ㆍ검증 API 호출 차단)은 완전히
    동일하다."""


def enforce_tier_system_boundaries(report, computed):
    """신규5개 시스템(tojeong/yukhyo/seongmyeonghak/pungsu/taekil) 중 이 tier가 허용하지
    않은 것이 실제 콘텐츠로 존재하면 하드 블록한다.

    허용 집합은 _TIER_REQUIRED_NEW_SYSTEMS 하나만으로 정의한다(정책 이중 정의 금지 —
    사용자 지시). 이 5개 체계는 "필수"와 "허용" 사이에 별도의 "선택적으로 있어도 되는"
    중간 상태가 없으므로(각 tier는 정확히 이만큼만 받기로 설계된 유료 상품 구성),
    forbidden = 전체 5개 - required로 그대로 도출해도 안전하다.

    main()에서 _merge_new_reference_systems_into_sections() 바로 뒤, ensure_required_
    new_engine_sections()(fallback) 앞에서 호출해야 한다 — 병합 전에는 new_reference_
    systems 경로로 들어온 위반을 못 보고(legacy system_sections 경로만 보임), 병합
    후여야 두 경로가 합쳐진 최종 system_sections를 정확히 판정할 수 있다.

    "실제 콘텐츠로 존재"의 판정 기준(_has_new5_body_content, body 10자 이상)은 병합
    함수의 판정 기준과 완전히 동일 — null/빈 객체({})는 병합 단계에서 이미 system_
    sections에 반영되지 않으므로(merge 함수 참고), 이 함수 시점에는 애초에 "진짜
    콘텐츠가 있는 항목"만 보게 된다. 별도의 null/empty 특수 처리를 추가하지 않는다."""
    tier = computed.get("tier")
    allowed = set(_TIER_REQUIRED_NEW_SYSTEMS.get(tier) or [])
    forbidden = set(_NEW5_SYSTEM_KEYS) - allowed

    sections = report.get("system_sections")
    if not isinstance(sections, list):
        return

    violations = sorted({
        s.get("system") for s in sections
        if isinstance(s, dict) and s.get("system") in forbidden and _has_new5_body_content(s)
    })
    if violations:
        raise ForbiddenTierSystemError(
            f"'{tier}' tier에 허용되지 않은 신규 참고시스템이 실제 콘텐츠로 생성됨: "
            f"{violations} — 이 리포트는 저장ㆍ발송하면 안 됨(고객이 구매하지 않은 상위 "
            "티어 콘텐츠가 포함될 위험). raw 백업(정규화 전 원본)을 확인해 재처리할 것."
        )


def check_hallucination(report, known_terms, valid_years):
    """리포트 본문에서 핵심 용어를 뽑아 known_terms/valid_years와 대조 — 발송을 막지는
    않고 경고만 남긴다.

    2026-08-24 추가 — 실제로 LLM이 action_plan을 dict가 아니라 문자열로 반환한 사례가
    있었음(원인 불명 — 스키마로 강제하는데도 발생. max_tokens 근처까지 간 대형 응답에서
    발생한 것으로 추정되나 확실친 않음). 그때 이 함수가 .get()을 그대로 호출하다
    AttributeError로 죽으면서, **이미 돈을 내고 받은 LLM 응답을 저장도 못 하고 통째로
    날렸다** — 검증 코드의 버그로 API 비용을 날리는 건 절대 안 되므로, 아래 모든 블록을
    isinstance로 방어해서 "이 필드가 예상과 다른 모양이어도 이 함수는 절대 죽지 않는다"를
    보장한다(무엇이 이상한지는 여전히 신호로 남기되, 죽지는 않게)."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    all_text = str(report.get("intro") or "") + str(report.get("closing") or "")
    for sec in _l(report.get("system_sections")):
        sec = _d(sec)
        all_text += str(sec.get("body") or "") + str(sec.get("key_insight") or "") + " ".join(_l(sec.get("takeaways")))
    all_text += str(_d(report.get("cross_analysis")).get("body") or "")
    for item in _l(report.get("opportunities")) + _l(report.get("risks")):
        item = _d(item)
        all_text += str(item.get("title") or "") + str(item.get("body") or "")
    action_plan = _d(report.get("action_plan"))
    for step in _l(action_plan.get("steps")):
        step = _d(step)
        all_text += str(step.get("label") or "") + str(step.get("desc") or "")
    for script in _l(action_plan.get("scripts")):
        script = _d(script)
        all_text += str(script.get("situation") or "") + str(script.get("line") or "")
    for q in _l(action_plan.get("reflection_questions")):
        q = _d(q)
        all_text += str(q.get("question") or "") + str(q.get("note") or "")
    for qa in _l(report.get("question_answers")):
        all_text += str(_d(qa).get("body") or "")
    for part in _d(report.get("long_term_strategy")).values():
        if isinstance(part, dict):
            all_text += str(part.get("body") or "")

    # 2026-08-24 — 이전엔 본문에 "%"가 있으면 무조건 경고했으나, 사용자 확인: "퍼센트가
    # 들어가는건 아무 문제가 없어. 오히려 좋은거야." 손님 본인의 실제 계산값을 %로 표현하는
    # 건 정상이고 권장되므로, 그 신호로는 더 이상 쓰지 않는다(진짜 위험한 건 %라는 기호가
    # 아니라 "다른 손님들과 비교한 근거 없는 통계"인데, 그건 %없이도 쓸 수 있고 %가 있다고
    # 반드시 그런 것도 아니라서 기계적으로 감지하기 어렵다 — 9-C번 프롬프트 규칙으로만 막음).

    # 2026-08-24 추가 — 7번 규칙("한자 절대 쓰지 말 것")이 실제로 여러 번 어겨진 걸 눈으로
    # 확인함(壬辰ㆍ華蓋殺 등, PDF에서 폰트가 없는 글자칸(tofu box)으로 깨짐). 처음엔 "한자
    # 범위(U+4E00–U+9FFF)만 스캔"으로 좁게 고쳤는데, 사용자가 "문제를 발견했으면 같은
    # 실수가 다시는 반복되지 않도록 원인 자체를 제거하라"고 지적함 — 한자는 이 폰트가 못
    # 그리는 여러 문자 종류 중 하나일 뿐이고, 다음엔 다른 미지원 기호(예: 이모지, 다른
    # 언어 문자)가 나올 수도 있다. 그래서 "한자인지"를 묻는 대신 "이 폰트가 실제로 그릴 수
    # 있는 글자인지"를 Pretendard TTF의 cmap(글리프 테이블)에서 직접 조회하는 방식으로
    # 바꿨다 — 원인(폰트가 못 그리는 모든 글자)을 통째로 막는 구조라, 한자든 다른 무엇이든
    # 이 폰트가 지원 안 하는 문자는 종류를 가리지 않고 전부 걸린다.
    unsupported = sorted({ch for ch in all_text if not _is_glyph_supported(ch)})
    if unsupported:
        # 2026-08-24 문구 수정 — 아래 sanitize_report()가 이 글자들을 저장 전에 실제로
        # 전부 제거하므로, 최종 PDF에는 절대 나타나지 않는다(방금 이 파일로 직접 검증함:
        # report.json·PDF 텍스트 추출 둘 다 클린). 그런데도 예전 문구("발송 전 반드시
        # 확인할 것")가 마치 최종 산출물이 아직 깨져 있는 것처럼 읽혀서, 이미 자동으로
        # 고쳐진 걸 보고도 "또 안 고쳤나" 오해를 부를 수 있었음 — 그래서 "이미 자동
        # 제거됨"이라고 명확히 밝히는 쪽으로 문구만 바꿈(로직은 그대로).
        print(f"ℹ 참고: LLM이 PDF 폰트가 못 그리는 문자를 시도함: {''.join(unsupported)} — 이미 자동으로 제거되어 최종 PDF에는 나타나지 않습니다. (7번 규칙을 얼마나 자주 어기는지 추적하는 용도, 조치 불필요)")
    else:
        print("✓ 본문의 모든 문자가 PDF 폰트에서 정상 렌더링됨")

    # 간지(2글자 한글, 예: "경오"), 별자리("~자리"로 끝남), 원소(단일 한글자+조사) 패턴만
    # 가볍게 검사 — 완벽한 NLP가 아니라 "발송 전 훑어볼 신호"로만 쓴다(설계 문서 참고).
    sign_candidates = re.findall(r"[가-힣]+자리", all_text)
    # 2026-08-29 수정 — 50회 2차 시뮬레이션에서 실제로 재현: "별자리"라는 일반 명사
    # 자체도 "자리"로 끝나서 이 정규식에 매번 걸림(특정 별자리 이름이 아니라 "별자리"라는
    # 단어 그 자체는 계산값 대조가 필요 없음) — 매번 오탐 경고가 났던 진짜 원인.
    GENERIC_JARI_WORDS = {"별자리"}
    unknown = [s for s in set(sign_candidates) if s not in known_terms and s not in GENERIC_JARI_WORDS]
    if unknown:
        print(f"⚠ 경고: 리포트에 computed.json에 없는 별자리 표현이 있을 수 있음: {unknown}")
    else:
        print("✓ 별자리 용어 대조 통과(단순 패턴 검사, 완벽하지 않음 — 최종 발송 전 사람이 한 번 읽을 것)")

    # 연도 대조 — se_un 없이 특정 연도를 언급했던 실제 사례를 계기로 추가함.
    year_candidates = {int(y) for y in re.findall(r"(?:19|20)\d{2}(?=년)", all_text)}
    unknown_years = year_candidates - valid_years
    if unknown_years:
        print(f"⚠ 경고: computed.json의 se_un/dae_yun/생년에 없는 연도 언급 발견: {sorted(unknown_years)} — AI가 일반 지식으로 채웠을 가능성, 발송 전 확인할 것")
    else:
        print("✓ 연도 언급 전부 se_un/dae_yun/생년 범위 안에 있음")


def _ensure_term_glosses_once(obj, gloss_map, seen):
    if isinstance(obj, str):
        # 2026-08-29 수정 — 실제 사고 재현: 겁재/정재처럼 서로의 뜻풀이 안에 서로를
        # 언급하는(가상의) 순환 관계를 넣고 적대적 테스트를 돌려보니, 용어를 하나씩
        # 순서대로 처리하며 그때그때 문자열을 바꿔버려서 "방금 삽입한 다른 용어의
        # 뜻풀이 안에 있는 텍스트"까지 같은 패스 안에서 또 훑어버렸다 — 그 결과 한 패스
        # 만으로도 여러 겹 중첩이 생기고, 바깥의 고정점 루프(최대 5회)가 그걸 계속
        # 키워서 읽을 수 없는 문장이 됐다. 고쳐서: 이 문자열의 "원본 스냅샷" 기준으로
        # 모든 용어의 위치를 한꺼번에 먼저 찾고, 삽입은 마지막에 한 번에(뒤에서부터)
        # 적용한다 — 한 패스 안에서는 삽입 순서가 서로에게 영향을 못 주게 만든 것.
        original = obj
        insertions = []  # (idx, term, gloss)
        for term in GLOSSARY_TERMS:
            gloss = gloss_map.get(term)
            if not gloss:
                continue
            # 2026-08-30 수정 — 원래는 "이 문자열 안에 이미 괄호가 있는가"만 봤는데,
            # 그러면 리포트 전체(다른 섹션)에서 이미 풀어쓴 용어를 이 문자열이 처음
            # 언급할 때 또 새로 풀어썼다(사용자 지적: "용어 뜻풀이가 리포트 전체에서
            # 너무 자주 반복된다"). expand_term_placeholders()와 이 함수가 함께 공유하는
            # `seen` 집합(리포트 전체 순회 기준)을 확인해, 어느 필드에서든 이미 풀어쓴
            # 용어면 이 문자열에서는 맨몸 그대로 둔다.
            if term in seen:
                continue
            # 2026-08-30 수정 — 삽입 형식을 "용어(뜻풀이)" → "뜻풀이(용어)"로 뒤집으면서,
            # "이미 뜻풀이가 붙었는가" 판정 기준도 같이 뒤집는다: 예전엔 "용어(" 뒤에
            # 괄호가 오는지 봤는데, 이제는 용어 자체가 "(용어)"처럼 괄호에 싸여 있는지
            # 본다(모델이 "칠살(편관)"처럼 스스로 결합 라벨을 쓴 경우도 이 형태로 걸림).
            if ("(" + term + ")") in original:
                seen.add(term)  # 모델이 스스로 붙인 뜻풀이도 "이미 설명됨"으로 리포트 전체에 반영
                continue
            start = 0
            found_here = False
            while True:
                idx = original.find(term, start)
                if idx == -1:
                    break
                before = original[max(0, idx - 3):idx].rstrip()
                if not before.endswith("("):
                    insertions.append((idx, term, gloss))
                    found_here = True
                    break  # 이 문자열 안에서는 첫 번째 맨몸 등장만 풀어주고 멈춘다
                start = idx + len(term)
            if found_here:
                seen.add(term)
        insertions.sort(key=lambda t: t[0], reverse=True)  # 뒤에서부터 삽입해야 앞쪽 위치가 안 밀림
        for idx, term, gloss in insertions:
            obj = obj[:idx] + f"{gloss}(" + term + ")" + obj[idx + len(term):]
        return obj
    if isinstance(obj, list):
        return [_ensure_term_glosses_once(v, gloss_map, seen) for v in obj]
    if isinstance(obj, dict):
        # expand_term_placeholders()와 같은 이유로 "heading"ㆍ"toc_preview"ㆍ"takeaways" 제외.
        return {
            k: (v if k in ("heading", "toc_preview", "takeaways") else _ensure_term_glosses_once(v, gloss_map, seen))
            for k, v in obj.items()
        }
    return obj


def ensure_term_glosses(obj, gloss_map, seen=None):
    """2026-08-29 추가 — check_term_glosses()는 경고만 했는데, 실제 100회 무료
    시뮬레이션(원본은 진짜 발송된 최광호 프리미엄 리포트)에서 100번 전부 똑같은
    경고("겁재ㆍ도화살ㆍ상관..." 등 14개 용어가 괄호 뜻풀이 없이 쓰임)가 반복됐다 —
    ensure_emphasis()와 똑같이 "경고는 있지만 아무도 안 읽고 그대로 나간다"는 걸
    이미 한 번 확인했으므로, 여기도 같은 원칙을 적용한다: 검증이 아니라 생성
    직후 데이터 자체를 코드가 직접 고친다.

    expand_term_placeholders()와 동작 방식은 같다(report 전체를 재귀로 훑으며 문자열만
    처리) — 다만 그건 `{{용어}}` 표시가 있는 자리만 채우고, 이건 모델이 `{{}}` 없이
    맨몸으로 써버린 GLOSSARY_TERMS까지 사후에 gloss_map으로 직접 감싼다. 이미 괄호가
    붙어있는 경우(모델이 스스로 뜻풀이를 붙였거나 "칠살(편관)"처럼 결합 라벨인 경우)는
    손대지 않는다 — check_term_glosses()와 동일한 판정 기준(뒤 3글자 내에 "("가
    있는가)을 그대로 씀.

    2026-08-29 수정 — 100회 시뮬레이션 실제 실행 중 발견: "홍염살"의 뜻풀이 원문
    자체가 "도화살처럼 이성에게..."로 시작한다(computed.json의 실제 데이터). 한 번만
    훑으면 "도화살"을 먼저 처리한 뒤 "홍염살"을 나중에 채워 넣는 과정에서 방금 새로
    생긴 "도화살" 언급을 다시 못 본다 — 그래서 두 번째 패스로 한 번 더 훑는다.

    2026-08-29 재수정 — "결과가 바뀌지 않을 때까지(최대 5회) 반복"이라던 이전 버전은
    적대적 테스트(겁재의 뜻풀이 안에 정재, 정재의 뜻풀이 안에 겁재를 서로 언급하는
    가상의 순환 관계)에서 5단계까지 중첩되어 읽을 수 없는 문장을 만드는 실제 사고를
    일으켰다 — "수렴이 보장된다"는 원래 판단이 틀렸다(서로를 참조하는 두 용어는
    수학적으로 절대 수렴하지 않고 매 패스 계속 자란다). 위 _ensure_term_glosses_once를
    "한 패스 안에서는 원본 스냅샷 기준으로 한꺼번에 삽입"하도록 고쳐 패스 내부 오염은
    막았지만, 패스 자체는 여전히 여러 번 돌면 서로 계속 자랄 수 있다 — 그래서 "바뀔
    때까지"가 아니라 **정확히 2번만** 돈다: 1패스=원본 용어, 2패스=1패스가 새로 만든
    용어(홍염살→도화살 같은 실제 사례) 이렇게 "정의 안의 정의"까지만 의도적으로
    지원하고, 그 이상(정의 안의 정의 안의 정의)은 지원하지 않는다 — 실제로 이 깊이가
    필요한 사례가 없었고, 지원하면 순환 관계에서 다시 무한히 자라기 때문이다.

    2026-08-30 수정 — `seen`(리포트 전체 기준 "이미 풀어쓴 용어" 집합)을 외부에서
    주입받을 수 있게 함. main()에서 expand_term_placeholders()가 쓴 것과 같은 집합을
    넘겨주면, `{{}}`로 명시한 용어와 맨몸으로 쓴 용어가 서로의 존재를 인지해 어느
    쪽으로 먼저 풀어썼든 리포트 전체에서 중복되지 않는다. 안 넘기면(단독 호출ㆍ기존
    테스트 호환) 이 호출 하나에서만 유효한 새 집합을 만든다."""
    if seen is None:
        seen = set()
    obj = _ensure_term_glosses_once(obj, gloss_map, seen)
    obj = _ensure_term_glosses_once(obj, gloss_map, seen)
    return obj


# 2026-08-30 추가 — report_kit.py 렌더링 순서를 기준으로 나눈 "챕터 묶음". 묶음이 바뀌면
# 용어를 처음 보는 것처럼 다시 설명하고, 같은 묶음 안에서는 반복하지 않는다.
_GLOSS_GROUPS = [
    ["intro", "system_sections"],
    ["cross_analysis", "opportunities", "risks", "action_plan", "long_term_strategy"],
    ["question_answers", "closing"],
]


def apply_term_glosses_by_group(report, gloss_map, unmapped_terms):
    """2026-08-30 추가 — 처음엔 리포트 전체(47페이지 전부)를 한 개의 공유 집합으로 묶어서
    "용어를 한 번만 풀어쓴다"를 구현했는데, 다시 검토해보니 이건 "같은 챕터 안에서
    반복된다"는 원래 불만을 없애려다 "한 번 설명하고 40페이지 뒤까지 다시는 설명 안
    함"이라는 새 결함을 만드는 것이었다 — 그 결함을 감지하던 check_term_glosses를
    새 설계에 맞춰 조정했을 뿐, 결함 자체를 없앤 게 아니었다(근본 원인을 옮겨놓고 안
    보이게만 한 것, 사용자 지적으로 재점검함). 그래서 "리포트 전체 한 번"이 아니라
    "챕터 묶음별로 한 번"으로 범위를 좁힌다(_GLOSS_GROUPS 참고) — 묶음이 바뀌면 처음
    보는 것처럼 다시 설명하고, 같은 묶음 안(예: 사주ㆍ점성술ㆍ타로가 이어지는
    system_sections)에서는 반복하지 않는다.

    main()뿐 아니라 시뮬레이션 스크립트에서도 똑같이 재사용할 수 있도록 별도 함수로
    뺐다 — main() 안에 인라인으로만 있으면 회귀 테스트가 이 로직을 실제로 검증하지
    못한다."""
    for group_keys in _GLOSS_GROUPS:
        seen = set()
        for k in group_keys:
            if report.get(k) is not None:
                report[k] = expand_term_placeholders(report[k], gloss_map, unmapped_terms, seen)
        for k in group_keys:
            if report.get(k) is not None:
                report[k] = ensure_term_glosses(report[k], gloss_map, seen)
    return report


def check_term_glosses(report):
    """2026-08-29 추가 — "전문용어는 등장하는 자리에서 예외 없이 괄호로 풀어주라"는 규칙이
    실제로 어겨진 사고(화개살이 뜻풀이 없이 그대로 나온 사례)를 계기로 신설. 이 규칙은
    "용어 뒤에 괄호가 있는가"라는 사람 판단이 필요 없는 기계적 사실이라, LLM 검증이
    아니라 여기서 정규식으로 직접 대조한다 — 판단이 필요 없는 규칙까지 모델의 성실함에
    기대면 이번처럼 규칙이 있어도 새어나간다.

    check_hallucination()과 같은 원칙: 발송을 막지 않고 경고만 남기며, 이 함수는 순수
    파이썬 로직이라 API 실패로 죽을 일 자체가 없다."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    all_text = str(report.get("intro") or "") + str(report.get("closing") or "")
    for sec in _l(report.get("system_sections")):
        sec = _d(sec)
        all_text += str(sec.get("body") or "") + str(sec.get("key_insight") or "") + " ".join(_l(sec.get("takeaways")))
    all_text += str(_d(report.get("cross_analysis")).get("body") or "")
    for item in _l(report.get("opportunities")) + _l(report.get("risks")):
        item = _d(item)
        all_text += str(item.get("title") or "") + str(item.get("body") or "")
    action_plan = _d(report.get("action_plan"))
    for step in _l(action_plan.get("steps")):
        all_text += str(_d(step).get("desc") or "")
    for qa in _l(report.get("question_answers")):
        all_text += str(_d(qa).get("body") or "")
    for part in _d(report.get("long_term_strategy")).values():
        if isinstance(part, dict):
            all_text += str(part.get("body") or "")

    # 2026-08-30 수정 — 실제 회귀 발견: ensure_term_glosses()가 "리포트 전체에서 한 번만
    # 풀어쓰고 그 다음부터는 라벨만 남긴다"로 바뀌면서(사용자 지적: 용어 뜻풀이가 리포트
    # 전체에서 너무 자주 반복됨), 이 검사가 "용어가 나오는 모든 자리에 괄호가 있어야
    # 한다"는 낡은 기준으로 매번 경고를 냈다(180케이스 시뮬레이션 전부 이 경고로 FAIL
    # 처리됨). 새 설계에서는 "이 리포트 어딘가에 최소 한 번은 풀어썼는가"만 확인해야
    # 맞다 — 두 번째부터 괄호 없이 나오는 건 버그가 아니라 의도된 동작이다.
    # 2026-08-30 수정 — 삽입 형식이 "용어(뜻풀이)" → "뜻풀이(용어)"로 뒤집혀서, "풀어썼다"의
    # 판정 기준도 "용어 뒤에 (" → "용어 앞에 ("로 뒤집는다.
    missing = []
    for term in GLOSSARY_TERMS:
        occurrences = list(re.finditer(re.escape(term), all_text))
        if not occurrences:
            continue
        glossed_at_least_once = any(
            all_text[max(0, m.start() - 3):m.start()].rstrip().endswith("(") for m in occurrences
        )
        if not glossed_at_least_once:
            missing.append(term)
    if missing:
        print(f"⚠ 경고: 다음 용어가 괄호 뜻풀이 없이 쓰인 곳이 있음 — 발송 전 확인할 것: {sorted(set(missing))}")
    else:
        print("✓ 용어 뜻풀이 누락 검사 통과")


def check_emphasis_markers(report):
    """2026-08-29 추가 — 실제 발송된 리포트(최광호, premium)를 열어보니 5-A번 "문단당
    강조 표시 1~3곳" 규칙이 3만 자 본문 전체에서 딱 1번만 지켜져 있었다. 그런데도 이
    사고를 아무도 몰랐던 이유는, verify_naturalness()의 9개 점검 항목 어디에도 강조
    표시 개수를 세는 항목이 없었기 때문이다 — "규칙은 있지만 검증 대상이 아니었던"
    구멍. check_term_glosses()와 같은 원칙: 판단이 필요 없는 순수 기계적 사실(별표
    두 개가 몇 번 나왔는가)이므로 LLM 판단 없이 정규식으로 직접 센다.

    문단(빈 줄로 구분된 블록, `##` 소제목ㆍ`[[CARD:...]]` 마커만 있는 블록은 제외)마다
    최소 1곳은 강조돼야 한다는 게 5-A번 규칙의 취지이므로, 그 개수를 최소 기준선으로
    삼는다(원문은 "1~3곳"이라 상한은 없음 — 여기선 하한만 검사). **2026-08-29 수정 —
    80회 3차 시뮬레이션에서 발견: 처음엔 "섹션 개수"를 기준선으로 썼는데, 소제목이
    여러 개라 문단이 여러 개인 섹션에서 그 기준이 실제 요구치보다 낮게 잡혔다 —
    ensure_emphasis()와 똑같이 문단 단위로 다시 세도록 수정."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    all_text = str(report.get("intro") or "") + str(report.get("closing") or "")
    sections = _l(report.get("system_sections"))
    minimum = 0
    for sec in sections:
        body = str(_d(sec).get("body") or "")
        all_text += body
        minimum += sum(1 for p in body.split("\n\n") if _is_content_paragraph(p))
    all_text += str(_d(report.get("cross_analysis")).get("body") or "")
    for item in _l(report.get("opportunities")) + _l(report.get("risks")):
        all_text += str(_d(item).get("body") or "")
    for qa in _l(report.get("question_answers")):
        all_text += str(_d(qa).get("body") or "")

    bold_count = len(re.findall(r"\*\*[^*]{1,120}\*\*", all_text))
    if bold_count < minimum:
        print(
            f"⚠ 경고: 강조 표시(**)가 {bold_count}번밖에 안 쓰였음(섹션 {minimum}개 기준 "
            f"최소 {minimum}번은 있어야 함, 5-A번 규칙) — 발송 전 확인할 것"
        )
    else:
        print(f"✓ 강조 표시 개수 검사 통과({bold_count}번)")


_CARD_MARKER_ONLY_RE = re.compile(r"^\[\[CARD:[^\]]*\]\]$")


def _find_first_sentence(text):
    """2026-08-29 추가 — 실제 사고 발견: 예전엔 정규식으로 "첫 마침표까지"를 찾았는데,
    십신ㆍ신살 뜻풀이 자체가 이미 완결된 문장(마침표 포함)이라 "편재(내가 다루는 재물
    중에서도 흘러 다니는 쪽입니다. 사업 수완이...)"처럼 괄호 *안*에 마침표가 있으면
    거기서 강조를 끊어버려 "**...쪽입니다.**" 뒤로 괄호가 안 닫힌 채 남는 사고가 실제
    PDF에서 확인됨. 괄호 안에 있는 마침표는 무시하고, 괄호 바깥(깊이 0)의 첫 마침표까지만
    문장으로 인정한다.

    2026-08-30 수정 — 적대적 테스트로 발견: 모델이 괄호를 닫지 않고 써버리면(예: 여는
    괄호 뒤에 닫는 괄호가 끝까지 안 나옴) depth가 끝까지 0으로 안 돌아와서 이 함수가
    None을 반환했다 — 그러면 호출부(ensure_emphasis/ensure_unanswerable_reason)가
    "문장부호가 아예 없을 때"와 똑같은 폴백(p.strip()[:120] 단순 글자수 자르기)으로
    떨어져서, 고쳤다고 생각했던 "문장 중간에서 잘림" 버그가 다른 경로로 재발했다.
    괄호가 안 닫혀도 본문 어딘가에 마침표는 있을 수 있으니, 깊이 0에서 못 찾으면
    깊이와 무관하게 발견한 마지막 문장부호까지는 재사용한다(완전히 문장부호가 없는
    경우에만 호출부의 120자 폴백으로 넘어가게 함)."""
    depth = 0
    last_punct_end = None
    for i, ch in enumerate(text):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth = max(0, depth - 1)
        elif ch in ".!?":
            if depth == 0:
                return text[:i + 1]
            last_punct_end = i + 1
    return text[:last_punct_end] if last_punct_end else None


def _is_content_paragraph(p):
    """## 소제목 줄이나 [[CARD:포지션]] 마커만 있는 문단은 강조 대상이 아니다(둘 다
    그 자체가 짧은 이름표ㆍ표시일 뿐 "문단"이 아님) — 2026-08-29 80회 3차 시뮬레이션에서
    다중 소제목 섹션(카드 2개짜리 타로 섹션 등)을 테스트하며 이 구분이 필요함을 확인."""
    p = p.strip()
    if not p:
        return False
    if p.startswith("##"):
        return False
    if _CARD_MARKER_ONLY_RE.match(p):
        return False
    return True


def ensure_emphasis(report):
    """2026-08-29 추가 — check_emphasis_markers()는 강조(**) 누락을 "경고"만 했는데,
    바로 그날 밤 실제 발송된 리포트(최광호, premium)에 그 경고가 찍혀 있었는데도
    아무도 안 보고 그대로 나간 사고가 났다. expand_term_placeholders()가 이미 증명한
    원칙을 여기도 그대로 적용한다 — "LLM이 규칙을 기억해서 지키길 바라지 말고,
    코드가 결과물 자체를 항상 보장한다." 검증(check_emphasis_markers)이 아니라 생성
    직후 데이터를 직접 고치는 단계.

    2026-08-29 수정 — 80회 3차 시뮬레이션에서 실제 발견: 5-A번 규칙은 "문단당" 1~3곳
    강조를 요구하는데, 처음 구현은 "섹션당" 1곳만 보장했다. 소제목(##)이 여러 개라
    사실상 문단이 여러 개인 섹션(카드 2장을 한 섹션에서 다루는 타로 등)에서는 그
    보장이 부족했다 — 그래서 섹션 전체가 아니라 문단(빈 줄로 구분된 블록)마다
    독립적으로 검사ㆍ보강한다. `##` 소제목 줄이나 `[[CARD:...]]` 마커만 있는 블록은
    강조 대상에서 제외(이름표ㆍ표시일 뿐 산문이 아니므로)."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    fixed = 0
    for sec in _l(report.get("system_sections")):
        sec = _d(sec)
        body = sec.get("body")
        if not isinstance(body, str) or not body.strip():
            continue

        insight = sec.get("key_insight")
        insight = insight.strip() if isinstance(insight, str) else None

        paragraphs = body.split("\n\n")
        changed = False
        for i, p in enumerate(paragraphs):
            if not _is_content_paragraph(p):
                continue
            if re.search(r"\*\*[^*]{1,120}\*\*", p):
                continue  # 이 문단엔 이미 강조가 있음

            target = None
            if insight and insight in p:
                target = insight
            else:
                target = _find_first_sentence(p.strip())
            if not target:
                # 2026-08-29 추가 — 적대적 테스트에서 발견: 문장부호(.!?)가 아예 없는
                # 문단은 여기서 target이 계속 None이라 강조가 하나도 안 붙었다(보장이
                # 깨지는 지점). 문장을 못 찾으면 문단 전체(너무 길면 앞부분만)를
                # 강조 대상으로 대신 쓴다 — 여전히 "이미 모델이 쓴 텍스트 재사용"이라
                # 1번 규칙(지어내지 않기) 위반이 아니다.
                target = p.strip()[:120] or None

            if target and target in p:
                paragraphs[i] = p.replace(target, f"**{target}**", 1)
                changed = True

        if changed:
            sec["body"] = "\n\n".join(paragraphs)
            fixed += 1

    if fixed:
        print(f"✓ 강조 표시 자동 보강 완료({fixed}개 섹션의 문단들에 모델이 이미 쓴 문장을 강조 처리함)")


def ensure_unanswerable_reason(report):
    """2026-08-29 추가 — 10번 규칙 정독 + 실제 프리미엄 리포트(최광호) 감사 중 발견:
    redirected/unanswerable 질문 5개(Q2ㆍQ4ㆍQ7ㆍQ8ㆍQ9) 전부 unanswerable_reason이
    null이었다. body 맨 앞에는 이유를 잘 썼는데(규칙이 요구하는 그대로), 별도
    필드로는 한 번도 안 옮겨졌다 — 이 필드는 PDF에서 손님 눈에 띄는 인용구 박스로
    따로 렌더링되는데(report_kit.py), null이면 그 박스 자체가 안 뜬다. 스키마에
    "redirected/unanswerable일 때만 채움"이라고만 적혀 있고 강제할 방법이 없어서
    매번 새는 구조 — ensure_emphasis()와 같은 원칙: 이미 모델이 body 맨 앞에 쓴
    설명을 그대로 재사용해 코드가 직접 채운다(새 텍스트를 지어내지 않음, 1번 규칙)."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    filled = 0
    deduped = 0
    for qa in _l(report.get("question_answers")):
        qa = _d(qa)
        if qa.get("answerability") not in ("redirected", "unanswerable"):
            continue
        body = qa.get("body")
        body_stripped = body.strip() if isinstance(body, str) else ""

        reason = qa.get("unanswerable_reason")
        if not reason:
            if not body_stripped:
                continue
            found = _find_first_sentence(body_stripped)
            reason = found if found else body_stripped[:120]  # 문장부호 없으면 앞부분이라도 재사용
            if reason:
                qa["unanswerable_reason"] = reason
                filled += 1

        # 2026-08-29 수정 — 실제 사고 발견(사용자 검수): 인용구 박스(reason)와 그
        # 바로 아래 본문(body) 둘 다에 똑같은 문장이 그대로 나란히 찍혀서 같은
        # 말을 두 번 하는 것처럼 보였다(Q2ㆍQ4에서 실제 확인).
        # 2026-08-30 수정 — "reason이 원래 비어있어서 방금 채운 경우"에만 이 중복 제거를
        # 걸었었는데, 10번 규칙 자체가 모델에게 "unanswerable_reason에 이유를 명시하고
        # body 맨 앞에도 그 이유를 먼저 밝히라"고 시키고 있어서, 모델이 규칙대로 둘 다
        # 직접 채운 경우(reason이 원래부터 있던 경우)엔 이 함수가 아예 손을 안 대 중복이
        # 그대로 남는 걸 재현 테스트로 확인함 — reason 출처(방금 채웠는지 모델이 원래
        # 썼는지)와 무관하게 항상 대조해야 진짜로 막힌다.
        if isinstance(reason, str) and reason and body_stripped.startswith(reason):
            rest = body_stripped[len(reason):].lstrip()
            new_body = rest if rest else body_stripped
            if new_body != body:
                qa["body"] = new_body
                deduped += 1

    msgs = []
    if filled:
        msgs.append(f"{filled}개 필드 채움(body 첫 문장 재사용)")
    if deduped:
        msgs.append(f"{deduped}개 중복 문장 제거(reason과 body 서두가 겹침)")
    if msgs:
        print(f"✓ unanswerable_reason 자동 보강 완료: {', '.join(msgs)}")


_COMPUTER_SPEAK_WORDS = ["계산", "데이터", "범위", "포함되어 있지"]


def check_unanswerable_reason_tone(report):
    """2026-08-29 추가 — ensure_unanswerable_reason()으로 필드를 채우다가 실제 발견:
    body 첫 문장 자체가 이미 10번 규칙이 명시적으로 금지한 컴퓨터 말투("계산",
    "포함되어 있지 않음" 등)를 쓰고 있었다(예: "삼재... 계산은 이번 진단에 포함되어
    있지 않아"). 규칙은 정확한 문구("포함되어 있지 않음")만 예로 들었는데 실제로는
    어미만 바꿔("포함되어 있지 않아") 빠져나간다 — 판단이 필요 없는 단어 매칭이라
    여기서 기계적으로 대조한다(check_term_glosses와 같은 성격)."""
    def _d(v):
        return v if isinstance(v, dict) else {}

    def _l(v):
        return v if isinstance(v, list) else []

    hits = []
    for qa in _l(report.get("question_answers")):
        qa = _d(qa)
        reason = qa.get("unanswerable_reason")
        if not isinstance(reason, str):
            continue
        for w in _COMPUTER_SPEAK_WORDS:
            if w in reason:
                hits.append((qa.get("question"), w))

    if hits:
        print("⚠ 경고: unanswerable_reason에 컴퓨터 말투 단어가 남아있음(10번 규칙) — 발송 전 확인할 것:")
        for q, w in hits:
            print(f"    - {q!r}: {w!r}")
    else:
        print("✓ unanswerable_reason 말투 검사 통과")


def verify_groundedness(report, computed):
    """check_hallucination()의 정규식 대조가 구조적으로 못 잡는 영역을 메운다 —
    "computed.json에 없는 단어"가 아니라 "computed.json에 있는 값과 다른 내용을,
    정상적인 단어로" 쓴 경우(예: 일간이 을목인데 본문엔 갑목이라고 쓴 경우, 십신을
    바꿔치기한 경우, cross_analysis에 없는 상관관계를 지어낸 경우). 이런 오류는
    check_hallucination()의 "허용 목록에 있는 단어인가" 검사를 그대로 통과하므로,
    실제로 computed.json과 본문을 다시 대조하는 별도 판단이 필요하다.

    생성(글쓰기)과 검증(대조)은 서로 다른 종류의 작업이라, 검증만 전담하는 별도
    호출이 같은 호출 안에서 스스로 확인하는 것보다 더 안정적으로 오류를 잡는다.

    2026-08-28 추가. check_hallucination()과 같은 원칙 적용: 경고만 남기고 발송을
    막지 않으며(아직 데이터가 부족해 어디서 막을지 판단할 근거가 없음 — 데이터가
    쌓이면 재검토), 이 함수 자체가 실패해도(API 에러ㆍ타임아웃 등) 본 파이프라인은
    절대 죽지 않는다 — 이미 돈을 낸 리포트 생성 결과를 이 부가 검증 때문에
    날리면 안 된다는 원칙은 check_hallucination() 도입 계기와 동일하다."""
    # try 블록 밖에서 먼저 검사 — try 안에 두면 'except Exception'이 이 차단 자체를
    # 삼켜서 "검증 호출 실패, 넘어감"으로만 찍히고 테스트가 실제로는 안전한지 알 수 없게 됨.
    _block_if_offline_test_mode("verify_groundedness")
    try:
        client = anthropic.Anthropic()
        prompt = (
            "아래는 사주ㆍ점성술ㆍ타로 계산 결과(계산값)와, 그 계산값만 근거로 작성됐어야 "
            "하는 리포트 본문입니다. 당신의 임무는 글쓰기가 아니라 대조입니다.\n\n"
            "리포트 본문에 나온 구체적 주장(예: 특정 십신ㆍ오행ㆍ간지를 언급하며 그 의미를 "
            "설명하는 문장, 특정 시기를 언급하며 그 시기의 흐름을 설명하는 문장, 두 체계 "
            "사이의 상관관계를 언급하는 문장)을 하나씩 계산값과 대조하세요. 문체ㆍ표현 "
            "방식ㆍ해석의 깊이는 평가 대상이 아닙니다 — 오직 \"이 구체적 사실이 계산값에 "
            "실제로 있는가, 계산값과 일치하는가\"만 확인하세요.\n\n"
            f"[계산값]\n```json\n{json.dumps(computed, ensure_ascii=False)}\n```\n\n"
            f"[리포트 본문]\n```json\n{json.dumps(report, ensure_ascii=False)}\n```\n\n"
            "근거 없거나 계산값과 다른 구체적 주장이 전혀 없으면 \"OK\"라고만 답하세요. "
            "있으면 각각을 다음 형식으로 나열하세요:\n"
            "- (어느 섹션인지) 주장 내용 — 계산값과 다른/없는 이유"
        )
        # 2026-09-03 — sonnet-5 호환성 조정(verify_naturalness/verify_field_groundedness와
        # 동일 이유). 이 프롬프트는 report+computed 전체를 담아 이미 긴데, thinking까지
        # 조용히 켜지면 max_tokens=1536 중 상당 부분을 사고에 먼저 써서 대조 결과 텍스트가
        # 잘릴 위험이 커진다.
        resp = client.messages.create(
            model=GROUNDEDNESS_MODEL,
            max_tokens=1536,
            thinking={"type": "disabled"},
            messages=[{"role": "user", "content": prompt}],
        )
        # 2026-08-30 추가 — API usage 계측 3단계. 기존 코드는 resp.content만 읽고 resp.usage를
        # 한 번도 참조하지 않아 이 호출의 토큰 사용량이 어디에도 안 남았음(그동안 확인 불가
        # 상태였던 원인) — 순수 관측용 로그만 추가, 검증 로직/반환값은 전혀 안 바뀜.
        api_usage.log_usage_record(api_usage.build_usage_record(
            call_purpose="verify_groundedness", model=GROUNDEDNESS_MODEL, usage=resp.usage,
            tier=computed.get("tier"), thinking_disabled=True,
        ))
        result = "".join(
            block.text for block in resp.content if getattr(block, "type", None) == "text"
        ).strip()
        if result.upper().startswith("OK"):
            print("✓ 의미 기반 근거 검증 통과 — 계산값과 다른 구체적 주장 발견되지 않음")
        else:
            print(
                "⚠ 경고: 의미 기반 근거 검증에서 문제 발견 — 발송 전 반드시 사람이 확인할 것:\n"
                f"{result}"
            )
    except Exception as e:  # noqa: BLE001 — 이 검증이 죽어도 본 파이프라인은 계속돼야 함
        print(f"⚠ 참고: 의미 기반 근거 검증 호출 실패({e}) — 이 검증만 건너뜀, 리포트 생성 자체엔 영향 없음")


QUESTION_LOG_PATH = HERE / "logs" / "question_answerability_log.jsonl"


def log_question_answerability(report, computed, log_path=QUESTION_LOG_PATH):
    """2026-08-23 추가 — "계산 불가능한 질문이 실제로 얼마나 되냐"를 추측(예: "극소수")이
    아니라 실측하기 위한 로그. 리포트를 만들 때마다 question_answers의 판정
    (direct/redirected/unanswerable)을 그대로 append한다 — 절대 덮어쓰지 않음, 계속
    쌓기만 함. 이 로그가 쌓이면 print_log_summary()로 실제 비율을 확인할 수 있다."""
    qas = report.get("question_answers") or []
    if not qas:
        return
    log_path.parent.mkdir(parents=True, exist_ok=True)
    with log_path.open("a", encoding="utf-8") as f:
        for qa in qas:
            record = {
                "logged_at": datetime.now(timezone.utc).isoformat(),
                "tier": computed.get("tier"),
                "scope": computed.get("scope"),
                "question": qa.get("question"),
                "answerability": qa.get("answerability"),
                "unanswerable_reason": qa.get("unanswerable_reason"),
            }
            f.write(json.dumps(record, ensure_ascii=False) + "\n")
    counts = Counter(qa.get("answerability") for qa in qas)
    print(f"질문 판정 로그 기록 완료: {dict(counts)} (누적 로그 위치: {log_path})")


NATURALNESS_PASS_LOG_PATH = HERE / "logs" / "naturalness_pass_log.jsonl"


def log_naturalness_pass_result(naturalness_result, rewrite_pass_results, complete, computed,
                                 log_path=NATURALNESS_PASS_LOG_PATH):
    """2026-09-03 추가 — Naturalness Detection→targeted rewrite 폐쇄 루프를 main()에
    처음 배선하면서 같이 추가한 감시 로그. log_question_answerability()와 동일한
    append-only 패턴 — "미해결 issue가 있었다"는 사실을 절대 덮어쓰거나 지우지 않고
    쌓기만 한다(나중에 print_log_summary처럼 실측 집계가 가능하도록).

    중요: complete=False여도 여기서 예외를 던지거나 리포트 저장을 막지 않는다.
    verify_naturalness()/verify_groundedness()가 이미 따르는 원칙("이미 돈을 낸
    리포트를 부가 검증 때문에 날리면 안 됨")을 그대로 따른다 — 이 함수의 역할은
    미해결 상태를 "조용히 사라지지 않게" 만드는 것뿐이고, 발송 여부를 결정하는
    게이트가 아니다."""
    resolved = sum(1 for r in rewrite_pass_results if r.get("accepted") is True)
    unresolved = [r for r in rewrite_pass_results if r.get("accepted") is not True]

    if naturalness_result.get("status") not in ("PASS", "ISSUES_FOUND"):
        print(
            f"⚠ 경고: naturalness Detection이 완료되지 못함(status={naturalness_result.get('status')}) "
            "— 이번 실행에서는 표현 품질 폐쇄 루프가 완료로 판정될 수 없음(발송 자체는 계속 진행됨)"
        )
    elif not rewrite_pass_results:
        print("✓ naturalness Detection: issue 없음 — 폐쇄 루프 완료(complete=True)")
    else:
        print(
            f"naturalness 폐쇄 루프: 총 {len(rewrite_pass_results)}건 중 {resolved}건 resolved, "
            f"{len(unresolved)}건 미해결(complete={complete})"
        )
        for r in unresolved:
            print(
                f"    - 미해결: {r.get('section_kind')}[{r.get('index')}].{r.get('field')} "
                f"category={r.get('category')} stage={r.get('stage')} — {r.get('reason')}"
            )

    log_path.parent.mkdir(parents=True, exist_ok=True)
    with log_path.open("a", encoding="utf-8") as f:
        f.write(json.dumps({
            "logged_at": datetime.now(timezone.utc).isoformat(),
            "tier": computed.get("tier"),
            "detection_status": naturalness_result.get("status"),
            "issue_count": len(naturalness_result.get("issues") or []),
            "resolved_count": resolved,
            "unresolved_count": len(unresolved),
            "complete": complete,
            "unresolved": [
                {
                    "category": r.get("category"), "stage": r.get("stage"), "reason": r.get("reason"),
                    "section_kind": r.get("section_kind"), "index": r.get("index"),
                    "system_or_key": r.get("system_or_key"), "field": r.get("field"),
                }
                for r in unresolved
            ],
        }, ensure_ascii=False) + "\n")


def print_log_summary(log_path=QUESTION_LOG_PATH):
    """지금까지 쌓인 로그로 실제 비율을 계산해서 보여준다 — "극소수"였는지 아닌지 추측이
    아니라 숫자로 확인. 사용법: python build_report.py --log-summary"""
    if not log_path.exists():
        print(f"로그 파일이 아직 없습니다({log_path}) — 리포트를 몇 건 생성한 뒤 다시 확인하세요.")
        return
    records = [json.loads(line) for line in log_path.read_text(encoding="utf-8").splitlines() if line.strip()]
    if not records:
        print("로그는 있지만 기록이 비어있습니다.")
        return
    total = len(records)
    counts = Counter(r["answerability"] for r in records)
    print(f"누적 질문 {total}건 (리포트 여러 건 합산):")
    for kind in ("direct", "redirected", "unanswerable"):
        n = counts.get(kind, 0)
        print(f"  {kind}: {n}건 ({n / total * 100:.1f}%)")
    unanswerable = [r for r in records if r["answerability"] == "unanswerable"]
    if unanswerable:
        print("\nunanswerable로 판정된 질문 예시(패턴 파악용, 최대 10개):")
        for r in unanswerable[:10]:
            print(f"  - {r['question']!r} ({r.get('unanswerable_reason')})")


def main():
    if len(sys.argv) >= 2 and sys.argv[1] == "--log-summary":
        print_log_summary()
        return

    if len(sys.argv) < 2:
        print("사용법: python build_report.py <computed.json> [출력 PDF 경로]")
        print("        python build_report.py --log-summary   (누적된 질문 판정 통계 확인)")
        sys.exit(1)

    computed_path = Path(sys.argv[1])
    computed = json.loads(computed_path.read_text(encoding="utf-8"))
    # 2026-09-03 추가 — STEP2(computed contract 안정화). enforce_purchased_core_systems_
    # present보다 먼저(=call_llm 호출 전) 실행해, 애초에 깨진 계산값으로 유료 API를
    # 호출하는 낭비 자체를 막는다. 이 예외는 잡지 않고 그대로 전파시켜 main()을
    # 완전히 중단시킨다(report.json 저장 전, raw_backup_path 관련 로직 전) — 같은
    # 하드블록 철학을 그대로 재사용.
    enforce_computed_core_contract(computed)

    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("ANTHROPIC_API_KEY 환경변수가 없음 — Anthropic Console에서 API 키 발급 필요")
        print("(계획서 8번 '사용자가 직접 해야 하는 일' 참고, 에이전트가 대신 만들 수 없음)")
        sys.exit(1)

    print(f"LLM 호출 중... (모델: {MODEL})")
    report, usage = call_llm(computed)
    print(f"완료. 토큰 사용량: 입력 {usage.input_tokens} / 출력 {usage.output_tokens}")

    out_path = Path(sys.argv[2]) if len(sys.argv) > 2 else computed_path.with_suffix(".report.json")
    # 2026-08-31 수정 — STEP9 사고 대응: 이전 코드는 normalize_to_schema() 호출 *뒤에*
    # "raw" 백업을 저장해서, LLM이 실제로 반환한 원본(예: system_sections가 문자열로
    # 왔던 그 상태)이 파이프라인 어디에도 한순간도 기록되지 않았다 — normalize_to_schema
    # 호출 *전*인 지금 이 시점의 report가 진짜 원본(call_llm()의 block.input 그대로)이다.
    # 이후 단계가 죽어도, 또는 정규화가 내용을 비워도 이 파일로 원인을 확인할 수 있다.
    raw_backup_path = out_path.with_suffix(".raw.json")
    raw_backup_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

    # 2026-08-24 추가 — 응답을 받는 즉시 스키마와 실제 타입을 대조해 정규화(normalize_to_
    # schema 문서화 참고). 이후의 모든 코드(이 파일의 검증 함수들 + report_kit.py의 PDF
    # 렌더링)는 이 시점부터 항상 스키마와 맞는 안전한 데이터만 보게 된다.
    schema_corrections = []
    report = normalize_to_schema(report, REPORT_SCHEMA["input_schema"], "report", schema_corrections)
    critical_corrections = [c for c in schema_corrections if c["severity"] == "CRITICAL"]
    minor_corrections = [c for c in schema_corrections if c["severity"] != "CRITICAL"]
    if critical_corrections:
        print(f"🚨 CRITICAL: LLM 응답의 최상위 구조 필드 {len(critical_corrections)}건이 "
              "타입 오류로 빈 값으로 대체됨 — 손님이 낸 돈만큼의 내용이 사라졌을 수 있음, "
              "발송 전 반드시 원본(아래 보존 경로)을 확인할 것:")
        for c in critical_corrections:
            print(f"    - {c['message']}")
    if minor_corrections:
        print(f"⚠ 경고: LLM 응답이 스키마와 맞지 않아 {len(minor_corrections)}건 자동 보정함 — 해당 부분은 리포트에서 비어있을 수 있으니 발송 전 확인할 것:")
        for c in minor_corrections:
            print(f"    - {c['message']}")

    # 2026-08-31 추가 — 데이터 손실(schema_corrections 발생)이 있으면 원본을 삭제하지
    # 않고, 어느 실행에서 발생했는지 추적 가능한 이름으로 영구 보존한다. 이 파일이
    # 남아있다는 사실 자체가 "이 주문에서 원본 손실이 있었다"는 증거가 된다.
    if schema_corrections:
        incident_stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
        incident_path = out_path.parent / f"{out_path.stem}.SCHEMA_INCIDENT_{incident_stamp}.raw.json"
        incident_path.write_text(raw_backup_path.read_text(encoding="utf-8"), encoding="utf-8")
        print(f"📁 원본 보존됨(스키마 보정 발생) — {incident_path}")

    # 2026-08-31 추가 — #4(타로 누락) 재발 방지. normalize_to_schema() 직후, 아직 아무
    # 유료 검증 호출(verify_groundedness/verify_naturalness)도 하기 전에 검사한다 —
    # 여기서 실패하면 그 검증 호출 비용도 아낀다. 이 예외는 잡지 않고 그대로 전파시켜
    # main()을 완전히 중단시킨다(report.json 저장 전, raw_backup_path.unlink() 전).
    enforce_purchased_core_systems_present(report, computed)

    # 2026-08-29 추가 — 모델이 `{{용어명}}`으로 표시만 해둔 자리에, 코드가 항상 정확한
    # 뜻풀이를 채워 넣는다. 검증(뒤의 check_term_glosses)이 아니라 생성 단계 자체를
    # 고치는 것 — 이 시점 이후로는 애초에 뜻풀이 누락ㆍ오류가 나올 수 없는 상태가 된다.
    gloss_map = build_term_gloss_map(computed)
    unmapped_terms = []
    apply_term_glosses_by_group(report, gloss_map, unmapped_terms)
    if unmapped_terms:
        print(f"⚠ 경고: {{}} 안에 사전에 없는 용어명이 있어 뜻풀이를 못 채움 — 발송 전 확인할 것: {sorted(set(unmapped_terms))}")
    else:
        print("✓ 용어 뜻풀이 자동 삽입 완료")

    # 2026-08-30 수정 — 실제 회귀 발견: ensure_emphasis()가 신규 시스템 섹션(아래
    # ensure_required_new_engine_sections)보다 먼저 실행되고 있어서, LLM이 안 써서 코드가
    # 대신 조립한 5개 섹션(토정비결ㆍ육효ㆍ성명학ㆍ풍수ㆍ택일)은 강조 처리 대상에서 아예
    # 빠졌다 — 그 섹션들이 통째로 강조 없는 밋밋한 텍스트로 남아 check_emphasis_markers가
    # "강조 부족" 경고를 내는 걸로 실제 확인함(프리미엄 샘플 재검증 중 발견). 신규 섹션을
    # 먼저 채운 뒤에 강조를 매겨야 그 섹션들도 빠짐없이 강조 대상이 된다.
    _merge_new_reference_systems_into_sections(report)  # 2026-09-01 추가(#3 D-2) — new_reference_systems(dict key)에 LLM이 채운 내용을 system_sections로 병합, 이후 로직은 전부 system_sections만 봄
    enforce_tier_system_boundaries(report, computed)  # 2026-09-01 추가(#16) — dual에 yukhyo가 실제로 생성된 사고 대응. 이 예외는 잡지 않고 그대로 전파시켜 main()을 중단시킨다(report.json 저장 전, raw_backup_path.unlink() 전) — enforce_purchased_core_systems_present와 동일한 하드블록 철학
    ensure_required_new_engine_sections(report, computed)  # 신규 5개 시스템 섹션이 빠지면(위 병합 후에도 없으면) computed.json 실제 값으로 코드가 직접 채움
    ensure_emphasis(report)  # 생성 단계 자체를 고침 — 강조 누락이 애초에 최종 산출물에 남을 수 없게 함
    ensure_unanswerable_reason(report)  # redirected/unanswerable 인용구 박스가 비지 않도록 body 첫 문장 재사용
    ensure_tarot_suit_tally(report, computed)  # 타로 카드 계열 개수를 LLM이 잘못 셌으면 computed.json 실제 값으로 문장의 수사를 코드가 직접 고침

    known_terms = collect_known_terms(computed)
    valid_years = collect_valid_years(computed)
    check_hallucination(report, known_terms, valid_years)  # 원본 그대로 측정 — 얼마나 자주 규칙을 어기는지 계속 눈으로 볼 것
    check_required_tier_sections(report, computed)  # 티어별 필수 섹션(신규 5개 시스템 등)이 실제로 있는지 대조
    check_tarot_suit_tally(report, computed)  # 위 ensure_tarot_suit_tally가 이미 고쳤어야 함 — 남아있다면 정규식이 못 잡은 새 패턴이라는 신호
    check_qa_count_and_order(report, computed)  # 고객이 낸 질문 개수ㆍ순서와 question_answers가 실제로 대응하는지 대조
    check_leftover_placeholders(report)  # TODOㆍFIXMEㆍDEBUGㆍ남은 {{}} 같은 잔재 문자열 검색
    check_aspect_consistency(report, computed)  # 본문의 "삼각/사각/육각/합/대립" 표현이 computed.astrology.aspects 실제 값과 맞는지 대조
    check_overclaim_topics(report)  # 건강ㆍ임신ㆍ로또ㆍ사망ㆍ법률ㆍ투자 주제에서 단정적 표현 검사
    check_qa_avoidance_ending(report)  # Q&A 답변이 회피형 표현으로 끝나는지 검사
    check_qa_duplicates_sections(report)  # Q&A 답변이 system_sections 본문과 완전히 같은 문장을 복사하는지 대조
    check_unanswerable_reason_tone(report)  # redirected/unanswerable 이유 문장에 컴퓨터 말투가 남았는지 대조
    check_term_glosses(report)  # 최종 안전망 — {{}}를 안 쓰고 용어를 그냥 맨몸으로 쓴 경우만 여기서 잡힘
    check_emphasis_markers(report)  # ensure_emphasis() 이후에도 남는 예외가 있는지 계속 눈으로 볼 것(항상 통과해야 정상)
    verify_groundedness(report, computed)  # 정규식으로 못 잡는 의미 단위 오류(값 바꿔치기 등) 대조
    naturalness_result = verify_naturalness(report, tier=computed.get("tier"))  # 사실은 맞는데 표현이 헷갈리거나 부자연스러운 문장 대조
    # 2026-09-03 추가 — Detection이 찾은 issue를 실제로 처리하는 폐쇄 루프를 여기서
    # 처음 실전에 배선한다(run_targeted_rewrite_pass()는 그동안 mock 검증 전용이었음).
    # ACCEPT된 rewrite는 report를 직접(in-place) 갈아 끼우므로 이후 단계(sanitize_report
    # 등)는 자동으로 갱신된 내용을 본다. complete가 False여도 리포트 저장ㆍ발송은
    # 절대 막지 않는다 — verify_naturalness()/verify_groundedness()와 동일한 원칙
    # ("이미 돈을 낸 리포트를 부가 검증 때문에 날리면 안 됨").
    rewrite_pass_results = run_targeted_rewrite_pass(report, computed, naturalness_result["issues"])
    naturalness_pass_complete = is_naturalness_pass_complete(naturalness_result, rewrite_pass_results)
    log_naturalness_pass_result(naturalness_result, rewrite_pass_results, naturalness_pass_complete, computed)

    # 2026-08-24 추가 — 위 경고는 "얼마나 자주 어겼는지" 계속 지켜보기 위한 것일 뿐,
    # 실제로 저장ㆍ발송되는 리포트에는 폰트가 못 그리는 글자가 아예 없어야 한다(사용자
    # 지시: "완벽하게 생성할 수 있는 폰트만 사용하도록, 한자는 빼버려"). 경고 후 사람이
    # 다시 눌러야만 고쳐지는 구조를 없애고, 여기서 실제로 제거해 최종 산출물은 항상
    # 안전하게 만든다.
    report = sanitize_report(report)

    log_question_answerability(report, computed)

    out_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"리포트 JSON 저장: {out_path}")
    # 2026-08-31 수정 — schema_corrections가 발생했으면(데이터 손실 있었음) raw 백업을
    # 삭제하지 않는다(사용자 지시 B — "원본 raw 백업을 삭제하지 말고 보존"). 손실이
    # 없었을 때만(최종 저장까지 문제없이 왔고 정규화도 아무것도 안 고쳤을 때만) 폴더에
    # 쌍둥이 파일이 계속 쌓이지 않도록 정리한다.
    if not schema_corrections:
        raw_backup_path.unlink(missing_ok=True)
    print("(PDF 생성은 report_kit.py 완성 후 build_pdf_from_report()로 이어서 처리)")


if __name__ == "__main__":
    main()
